            )
          })}
        </div>
      )}
    </div>
  )
}

"use client"

import { useState, useTransition, useMemo } from "react"
import Link from "next/link"
import Image from "next/image"
import { useRouter } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Trash2, Minus, Plus, ShoppingBag, Store, AlertCircle } from "lucide-react"
import { updateCartQuantity, removeFromCart, checkoutCart } from "@/app/actions/cart"
import { toast } from "sonner"
import { formatPrice } from "@/lib/utils"
import { useTranslations } from "next-intl";

export function CartView({ initialItems }: { initialItems: Record<string, any>[] }) {
    const t = useTranslations();
  const [items, setItems] = useState(initialItems)
  const [isPending, startTransition] = useTransition()
  const [isCheckingOut, setIsCheckingOut] = useState(false)
  const router = useRouter()

  const groupedItems = useMemo(() => {
    const groups: Record<string, { sellerName: string, items: typeof items }> = {}
    items.forEach(item => {
      const sellerId = item.listings?.seller_id || "unknown"
      const sellerName = item.listings?.profiles?.full_name || "Неизвестный продавец"
      if (!groups[sellerId]) {
        groups[sellerId] = { sellerName, items: [] }
      }
      groups[sellerId].items.push(item)
    })
    return groups
  }, [items])

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center text-center py-24 px-4 border border-dashed rounded-3xl bg-muted/10">
        <div className="w-20 h-20 bg-muted rounded-full flex items-center justify-center mb-6">
          <ShoppingBag className="w-10 h-10 text-muted-foreground" />
        </div>
        <h2 className="text-2xl font-bold mb-3">{t("vasha_korzina_pusta")}</h2>
        <p className="text-muted-foreground mb-8 max-w-sm text-lg">
          {t("dobavte_tovary_iz_kataloga")}</p>
        <Button size="lg" asChild className="rounded-xl px-8">
          <Link href="/catalog">{t("pereyti_v_katalog")}</Link>
        </Button>
      </div>
    );
  }

  const handleUpdateQuantity = (cartItemId: string, newQuantity: number, maxAmount: number, type: string) => {
    if (type === "SINGLE" && newQuantity > 1) return
    if (newQuantity <= 0) {
      handleRemove(cartItemId)
      return
    }
    if (newQuantity > maxAmount) {
      toast.error(`Доступно только ${maxAmount} шт.`)
      return
    }
    
    // Optimistic update
    setItems(items.map(i => i.id === cartItemId ? { ...i, quantity: newQuantity } : i))
    
    startTransition(async () => {
      const res = await updateCartQuantity(cartItemId, newQuantity)
      if (res.error) {
        toast.error(res.error)
        router.refresh()
      }
    })
  }

  const handleRemove = (cartItemId: string) => {
    setItems(items.filter(i => i.id !== cartItemId))
    startTransition(async () => {
      const res = await removeFromCart(cartItemId)
      if (res.error) {
        toast.error(res.error)
        router.refresh()
      }
    })
  }

  const handleCheckout = async () => {
    setIsCheckingOut(true)
    const res = await checkoutCart()
    if (res.error) {
      toast.error(res.error)
      setIsCheckingOut(false)
    } else {
      toast.success("Заказ успешно оформлен!")
      if (res.orderIds && res.orderIds.length === 1) {
        router.push(`/orders/${res.orderIds[0]}`)
      } else {
        router.push("/orders")
      }
    }
  }

  const total = items.reduce((acc, item) => {
    if (item.listings?.status !== "ACTIVE") return acc
    return acc + (parseFloat(item.listings.price) * item.quantity)
  }, 0)

  const hasUnavailableItems = items.some(i => i.listings?.status !== "ACTIVE" || i.quantity > (i.listings?.listing_type === "INVENTORY" ? i.listings.quantity : 1))

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
      <div className="lg:col-span-2 space-y-8">
        {Object.entries(groupedItems).map(([sellerId, group]) => (
          <div key={sellerId} className="space-y-4">
            {/* Seller Header */}
            <div className="flex items-center gap-2 px-1">
              <Store className="w-5 h-5 text-muted-foreground" />
              <h2 className="font-semibold text-lg">{group.sellerName}</h2>
            </div>
            
            <div className="space-y-4">
              {group.items.map((item) => {
                const listing = item.listings
                if (!listing) return null
                
                const isSingle = listing.listing_type === "SINGLE"
                const stock = isSingle ? 1 : listing.quantity
                const maxAmount = stock
                
                const isUnavailable = listing.status !== "ACTIVE"
                const isOverStock = item.quantity > maxAmount
                const hasError = isUnavailable || isOverStock

                const images = (listing.listing_images || []).sort((a: any, b: any) => (a.order_index || 0) - (b.order_index || 0))
                const imageUrl = images.length > 0 ? images[0].url : "https://placehold.co/400x400?text=No+Image"
                
                return (
                  <div key={item.id} className={`flex gap-3 sm:gap-4 p-4 border rounded-2xl bg-card transition-colors ${hasError ? "border-destructive/50 bg-destructive/5" : ""}`}>
                    <Link href={`/product/${listing.id}`} className="shrink-0">
                      <div className="relative w-20 h-20 sm:w-28 sm:h-28 rounded-lg overflow-hidden bg-muted">
                        <Image src={imageUrl} alt={listing.title} fill className="object-cover" />
                        {isUnavailable && (
                          <div className="absolute inset-0 bg-background/60 backdrop-blur-[2px] flex items-center justify-center">
                            <span className="bg-destructive text-destructive-foreground text-[10px] sm:text-xs font-bold px-2 py-1 rounded">
                              {listing.status === "SOLD" ? "ПРОДАНО" : "НЕДОСТУПНО"}
                            </span>
                          </div>
                        )}
                      </div>
                    </Link>

                    <div className="flex-1 flex flex-col justify-between min-w-0">
                      <div>
                        <div className="flex justify-between items-start gap-4">
                          <Link href={`/product/${listing.id}`} className={`font-medium sm:font-semibold hover:underline line-clamp-2 ${isUnavailable ? "text-muted-foreground" : ""}`}>
                            {listing.title}
                          </Link>
                          <div className="font-bold whitespace-nowrap text-right">
                            {formatPrice(listing.price)}
                            {item.quantity > 1 && !hasError && (
                              <div className="text-xs text-muted-foreground font-normal mt-0.5">
                                {formatPrice(parseFloat(listing.price) * item.quantity)}
                              </div>
                            )}
                          </div>
                        </div>
                        
                        {hasError && (
                          <div className="flex items-center gap-1.5 mt-2 text-sm text-destructive">
                            <AlertCircle className="w-4 h-4 shrink-0" />
                            <span>
                              {isUnavailable 
                                ? "Товар больше недоступен для заказа" 
                                : `Доступно только ${stock} шт.`}
                            </span>
                          </div>
                        )}
                      </div>
                      
                      <div className="flex items-center justify-between mt-4">
                        {!isUnavailable ? (
                          <div className="flex flex-wrap items-center gap-3">
                            <div className="flex items-center border rounded-full overflow-hidden bg-background">
                              <button 
                                disabled={isPending}
                                onClick={() => handleUpdateQuantity(item.id, item.quantity - 1, maxAmount, listing.listing_type)}
                                className="w-8 h-8 sm:w-9 sm:h-9 flex items-center justify-center hover:bg-muted disabled:opacity-50 transition-colors"
                                aria-label={item.quantity === 1 ? "Удалить товар" : "Уменьшить количество"}
                              >
                                {item.quantity === 1 ? <Trash2 className="w-3.5 h-3.5 text-destructive" /> : <Minus className="w-3 h-3" />}
                              </button>
                              <span className="w-8 sm:w-10 text-center text-sm font-medium">{item.quantity}</span>
                              <button 
                                disabled={isPending || item.quantity >= maxAmount || isSingle}
                                onClick={() => handleUpdateQuantity(item.id, item.quantity + 1, maxAmount, listing.listing_type)}
                                className="w-8 h-8 sm:w-9 sm:h-9 flex items-center justify-center hover:bg-muted disabled:opacity-50 transition-colors"
                                aria-label={t("uvelichit_kolichestvo")}
                              >
                                <Plus className="w-3 h-3" />
                              </button>
                            </div>
                            {!isSingle && !isOverStock && (
                              <span className="text-xs text-muted-foreground">{t("v_nalichii")}{stock}</span>
                            )}
                          </div>
                        ) : (
                          <div /> // Spacer for flex-between
                        )}
                        
                        <Button 
                          variant="ghost" 
                          size="icon" 
                          className="text-muted-foreground hover:text-destructive shrink-0"
                          onClick={() => handleRemove(item.id)}
                          disabled={isPending}
                          aria-label={t("udalit_iz_korziny")}
                        >
                          <Trash2 className="w-5 h-5" />
                        </Button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>

      {/* Summary Sidebar */}
      <div>
        <div className="bg-muted/10 border p-5 sm:p-6 rounded-3xl sticky top-24">
          <h3 className="font-bold text-xl mb-6">{t("vash_zakaz")}</h3>
          
          <div className="space-y-4 mb-6 text-sm">
            <div className="flex justify-between">
              <span className="text-muted-foreground">
                {t("tovary")}{items.filter(i => i.listings?.status === "ACTIVE").reduce((acc, i) => acc + i.quantity, 0)})
              </span>
              <span className="font-medium">{formatPrice(total)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-muted-foreground">{t("dostavka")}</span>
              <span className="text-right">{t("rasschityvaetsya")}<br/>{t("otdelno_prodavtsom")}</span>
            </div>
          </div>
          
          <div className="border-t pt-5 mb-6">
            <div className="flex justify-between items-end">
              <span className="font-bold text-lg">{t("itogo")}</span>
              <span className="font-bold text-2xl">{formatPrice(total)}</span>
            </div>
          </div>
          
          <Button 
            className="w-full h-14 text-lg rounded-xl font-semibold shadow-sm" 
            onClick={handleCheckout}
            disabled={isCheckingOut || isPending || hasUnavailableItems || total === 0}
          >
            {isCheckingOut ? "Оформление..." : "Оформить заказ"}
          </Button>

          {hasUnavailableItems && (
            <p className="text-sm text-destructive mt-4 text-center font-medium bg-destructive/10 p-3 rounded-lg">
              {t("udalite_nedostupnye_tovary_ili")}</p>
          )}
          
          {!hasUnavailableItems && (
            <p className="text-xs text-muted-foreground text-center mt-4 px-2 leading-relaxed">
              {t("nazhimaya_oformit_zakaz_vy_otpravlyaete")}
            </p>
          )}
        </div>
      </div>
    </div>
  );
}

"use server"

import { createClient } from "@/lib/supabase/server"
import { getAllDescendantIds } from "@/lib/categories"

export async function fetchNextCatalogPage(searchParams: any, categories: any[], page: number) {
  const supabase = await createClient()
  if (!supabase) return []

  let query;
  const rawQ = searchParams.q?.trim()

  if (rawQ) {
    query = supabase
      .rpc("search_catalog_listings", { query_text: rawQ })
      .select(`
        *,
        profiles!seller_id(id, full_name),
        categories!inner(id, name, slug),
        listing_images(url, order_index)
      `)
  } else {
    query = supabase
      .from("listings")
      .select(`
        *,
        profiles!seller_id(id, full_name),
        categories!inner(id, name, slug),
        listing_images(url, order_index)
      `)
      .eq("status", "ACTIVE")
  }

  if (searchParams.category) {
    const targetCat = categories.find(c => c.slug === searchParams.category)
    if (targetCat) {
      const targetIds = [targetCat.id, ...getAllDescendantIds(categories, targetCat.id)]
      query = query.in("category_id", targetIds)
    } else {
      query = query.eq("categories.slug", searchParams.category)
    }
  }
  if (searchParams.city && searchParams.city !== "all") {
    query = query.eq("city", searchParams.city)
  }
  if (searchParams.region && searchParams.region !== "all") {
    query = query.eq("region", searchParams.region)
  }
  if (searchParams.minPrice) {
    query = query.gte("price", parseFloat(searchParams.minPrice))
  }
  if (searchParams.maxPrice) {
    query = query.lte("price", parseFloat(searchParams.maxPrice))
  }
  if (searchParams.condition) {
    query = query.eq("condition", searchParams.condition)
  }

  const sort = searchParams.sort || "newest"
  if (sort === "oldest") query = query.order("created_at", { ascending: true })
  else if (sort === "cheapest") query = query.order("price", { ascending: true })
  else if (sort === "expensive") query = query.order("price", { ascending: false })
  else if (sort === "newest" && !rawQ) {
    query = query.order("created_at", { ascending: false })
  }

  const limit = 20
  const from = (page - 1) * limit
  const to = from + limit - 1
  query = query.range(from, to)

  const { data: listings, error } = await query
  if (error || !listings) return []

  let favoriteIds = new Set<string>()
  const { data: { session } } = await supabase.auth.getSession()

  if (session && listings.length > 0) {
    const listingIds = listings.map((l: any) => l.id)
    const { data: favs } = await supabase
      .from("favorites")
      .select("listing_id")
      .eq("user_id", session.user.id)
      .in("listing_id", listingIds)

    if (favs) {
      favs.forEach((f: any) => favoriteIds.add(f.listing_id))
    }
  }

  return listings.map((l: any) => {
    const images = l.listing_images?.sort((a: any, b: any) => a.order_index - b.order_index) || []
    return {
      id: l.id,
      title: l.title,
      price: l.price,
      city: l.city,
      time: new Date(l.created_at).toLocaleDateString(),
      condition: l.condition,
      seller: { name: l.profiles?.full_name || "Пользователь" },
      image: images.length > 0 ? images[0].url : "",
      isVerified: false,
      isFavorite: favoriteIds.has(l.id)
    }
  })
}

import { Suspense } from "react"
import Link from "next/link"
import { createClient } from "@/lib/supabase/server"
import { ProductCard } from "@/components/shared/product-card"
import { ProductSkeleton } from "@/components/shared/product-skeleton"
import { Button } from "@/components/ui/button"
import { CatalogFiltersWidget } from "@/features/catalog/components/catalog-filters-widget"
import { CatalogSort } from "@/features/catalog/components/catalog-sort"
import { CatalogActiveFilters } from "@/features/catalog/components/catalog-active-filters"
import { CatalogLoadMore } from "@/features/catalog/components/catalog-load-more"
import { getAllDescendantIds, getCategoryBreadcrumbs } from "@/lib/categories"
import { useTranslations } from "next-intl";
import { getTranslations } from "next-intl/server";

export const metadata = {
  title: "Каталог товаров | BazarGo"
}

async function CatalogList({ searchParams, categories }: { searchParams: any, categories: any[] }) {
    const t = await getTranslations();
  const supabase = await createClient()
  if (!supabase) return <div>{t("oshibka_bazy_dannyh")}</div>;
  
  let query;
  const rawQ = searchParams.q?.trim()
  
  if (rawQ) {
    query = supabase
      .rpc("search_catalog_listings", { query_text: rawQ })
      .select(`
        *,
        profiles!seller_id(id, full_name),
        categories!inner(id, name, slug),
        listing_images(url, order_index)
      `, { count: "exact" })
  } else {
    query = supabase
      .from("listings")
      .select(`
        *,
        profiles!seller_id(id, full_name),
        categories!inner(id, name, slug),
        listing_images(url, order_index)
      `, { count: "exact" })
      .eq("status", "ACTIVE")
  }
    
  // Filters
  if (searchParams.category) {
    const targetCat = categories.find(c => c.slug === searchParams.category)
    if (targetCat) {
      const targetIds = [targetCat.id, ...getAllDescendantIds(categories, targetCat.id)]
      query = query.in("category_id", targetIds)
    } else {
      query = query.eq("categories.slug", searchParams.category)
    }
  }
  if (searchParams.city && searchParams.city !== "all") {
    query = query.eq("city", searchParams.city)
  }
  if (searchParams.region && searchParams.region !== "all") {
    query = query.eq("region", searchParams.region)
  }
  if (searchParams.minPrice) {
    query = query.gte("price", parseFloat(searchParams.minPrice))
  }
  if (searchParams.maxPrice) {
    query = query.lte("price", parseFloat(searchParams.maxPrice))
  }
  if (searchParams.condition) {
    query = query.eq("condition", searchParams.condition)
  }
  if (searchParams.b2b === "true") {
    query = query.eq("is_b2b", true)
  }

  // Sorting
  const sort = searchParams.sort || "newest"
  if (sort === "oldest") query = query.order("created_at", { ascending: true })
  else if (sort === "cheapest") query = query.order("price", { ascending: true })
  else if (sort === "expensive") query = query.order("price", { ascending: false })
  else if (sort === "newest" && !rawQ) {
    // Only apply default newest sort if not searching, to preserve search relevance ranking
    query = query.order("created_at", { ascending: false })
  }

  // Pagination (MVP offset-limit is fine with indexes, but cap max page)
  let page = parseInt(searchParams.page || "1")
  if (isNaN(page) || page < 1) page = 1
  if (page > 50) page = 50 // Protect against deep offset scanning

  const limit = 20
  const from = (page - 1) * limit
  const to = from + limit - 1
  query = query.range(from, to)
  
  const { data: listings, error, count } = await query
    
  if (error) {
    console.error("Catalog Fetch Error:", error)
    return (
      <div className="p-8 text-center text-destructive bg-destructive/10 rounded-xl">
        {t("ne_udalos_zagruzit_tovary")}<br/>
        <span className="text-xs">{error.message}</span>
        <Button variant="outline" asChild className="mt-4"><a href="/catalog">{t("sbrosit_filtry")}</a></Button>
      </div>
    );
  }

  if (!listings || listings.length === 0) {
    const isFiltered = Object.keys(searchParams).some(k => k !== 'page' && k !== 'sort')
    return (
      <div className="flex flex-col items-center justify-center text-center py-24 px-4 border border-dashed rounded-3xl bg-muted/10">
        <div className="w-20 h-20 bg-muted rounded-full flex items-center justify-center mb-6">
          <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-muted-foreground"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/></svg>
        </div>
        <h2 className="text-2xl font-bold mb-3">
          {rawQ ? `По запросу «${rawQ}» ничего не найдено` : "Ничего не нашли"}
        </h2>
        <p className="text-muted-foreground mb-8 max-w-md text-lg">
          {isFiltered 
            ? "Попробуйте смягчить условия поиска или убрать некоторые фильтры." 
            : "Попробуйте поискать что-нибудь другое или создайте запрос на покупку."}
        </p>
        <div className="flex flex-col sm:flex-row gap-4">
          {isFiltered && (
            <Button variant="outline" size="lg" asChild className="rounded-xl">
              <a href="/catalog">{t("sbrosit_vse_filtry")}</a>
            </Button>
          )}
          <Button size="lg" asChild className="rounded-xl">
            <a href="/requests">{t("sozdat_zapros")}</a>
          </Button>
        </div>
      </div>
    );
  }

  // Fetch favorites
  let favoriteIds = new Set<string>()
  const { data: { session } } = await supabase.auth.getSession()
  
  if (session && listings.length > 0) {
    const listingIds = listings.map((l: any) => l.id)
    const { data: favs } = await supabase
      .from("favorites")
      .select("listing_id")
      .eq("user_id", session.user.id)
      .in("listing_id", listingIds)
      
    if (favs) {
      favs.forEach((f: any) => favoriteIds.add(f.listing_id))
    }
  }

  let breadcrumbs: string[] = []
  if (searchParams.category) {
    const path = getCategoryBreadcrumbs(categories, searchParams.category)
    breadcrumbs = path.map(c => c.name)
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <p className="text-sm text-muted-foreground mb-1">
            {t("katalog")}{breadcrumbs.length > 0 && <span className="text-foreground">/ {breadcrumbs.join(" / ")}</span>}
          </p>
          <p className="text-sm font-medium">{t("naydeno")}{count} {t("tovarov")}</p>
        </div>

        {/* Desktop Sorting */}
        <CatalogSort sort={sort} />
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
        {listings.map((l: any) => {
          const images = l.listing_images?.sort((a: any, b: any) => a.order_index - b.order_index) || []
          const product = {
            id: l.id,
            title: l.title,
            price: l.price,
            city: l.city,
            time: new Date(l.created_at).toLocaleDateString(),
            condition: l.condition,
            seller: { name: l.profiles?.full_name || "Пользователь" },
            image: images.length > 0 ? images[0].url : "",
            isVerified: false,
            isFavorite: favoriteIds.has(l.id),
            isB2b: l.is_b2b,
            wholesalePrice: l.wholesale_price,
            minOrderQuantity: l.min_order_quantity
          }
          return <ProductCard key={l.id} product={product} />
        })}
      </div>

      <CatalogLoadMore 
        initialPage={page} 
        searchParams={searchParams} 
        totalCount={count || 0} 
        categories={categories} 
      />
    </div>
  );
}

