import { createClient } from "@/lib/supabase/server"
import { notFound, redirect } from "next/navigation"
import Link from "next/link"
import { ArrowLeft, Store } from "lucide-react"
import { ChatRoom } from "@/features/chat/components/chat-room"
import { BlockButton } from "@/features/blocks/components/block-button"
import { ReportModal } from "@/features/reports/components/report-modal"
import { useTranslations } from "next-intl";
import { getTranslations } from "next-intl/server";

export default async function ChatPage(props: { params: Promise<{ id: string }> }) {
    const t = await getTranslations();
  const params = await props.params;
  const { id } = params;
  
  const supabase = await createClient()
  const { data: { session } } = await supabase.auth.getSession()

  if (!session) {
    redirect("/login")
  }

  // Fetch chat
  const { data: chat, error } = await supabase
    .from("chats")
    .select(`
      *,
      listings(id, title, price, status, listing_images(url)),
      buyer:buyer_id(id, full_name, avatar_url),
      seller:seller_id(id, full_name, avatar_url)
    `)
    .eq("id", id)
    .single()

  if (error || !chat) {
    notFound()
  }

  // Verify access
  if (chat.buyer_id !== session.user.id && chat.seller_id !== session.user.id) {
    notFound()
  }

  // Fetch initial messages (last 50)
  const { data: rawMessages } = await supabase
    .from("messages")
    .select("*")
    .eq("chat_id", id)
    .order("created_at", { ascending: false })
    .limit(50)

  const messages = rawMessages ? [...rawMessages].reverse() : []

  // Fetch B2B Offers
  const { data: b2bOffers } = await supabase
    .from("b2b_offers")
    .select("*")
    .eq("chat_id", id)
    .order("created_at", { ascending: true })
  const isBuyer = session.user.id === chat.buyer_id
  const otherUser = isBuyer ? chat.seller : chat.buyer
  const listing = chat.listings

  // Check block status
  const { data: blockData } = await supabase
    .from("user_blocks")
    .select("blocker_id")
    .or(`and(blocker_id.eq.${session.user.id},blocked_id.eq.${otherUser.id}),and(blocker_id.eq.${otherUser.id},blocked_id.eq.${session.user.id})`)

  const isBlockedByMe = blockData?.some((b: any) => b.blocker_id === session.user.id) || false
  const isBlockedByThem = blockData?.some((b: any) => b.blocker_id === otherUser.id) || false
  const isBlocked = isBlockedByMe || isBlockedByThem

  return (
    <div className="flex flex-col flex-1 bg-background relative w-full min-w-0 overflow-hidden">
      {/* Messenger Header */}
      <div className="flex items-center justify-between px-2 sm:px-4 py-2.5 sm:py-3 border-b bg-background/95 backdrop-blur z-20 shrink-0">
        <div className="flex items-center gap-2 sm:gap-3 min-w-0">
          <Link href="/messages" className="md:hidden p-2 -ml-2 text-muted-foreground hover:text-foreground transition-colors rounded-full active:bg-muted">
            <ArrowLeft className="w-5 h-5" />
          </Link>
          <div className="w-9 h-9 sm:w-10 sm:h-10 bg-muted/50 rounded-full flex items-center justify-center text-muted-foreground font-bold overflow-hidden shrink-0 border shadow-sm">
            {otherUser?.avatar_url ? (
              <img src={otherUser.avatar_url} className="w-full h-full object-cover" />
            ) : (
              otherUser?.full_name?.charAt(0) || "U"
            )}
          </div>
          <div className="min-w-0 flex flex-col">
            <div className="flex items-center gap-1.5">
              <h1 className="font-bold text-[15px] sm:text-base leading-tight truncate">{otherUser?.full_name}</h1>
              <span className="hidden sm:inline-block w-1 h-1 bg-muted-foreground/30 rounded-full" />
              <span className="hidden sm:inline-block text-[13px] text-muted-foreground">{isBuyer ? "Продавец" : "Покупатель"}</span>
            </div>
            {listing ? (
              <Link href={`/product/${listing.id}`} className="text-[12px] sm:text-[13px] font-medium text-primary hover:underline truncate mt-0.5">
                {listing.title} <span className="text-muted-foreground font-normal ml-1">· {listing.price?.toLocaleString("ru-RU")} {t("som")}</span>
              </Link>
            ) : (
              <span className="text-[12px] sm:text-[13px] font-medium text-muted-foreground truncate mt-0.5">
                {t("obyavlenie_nedostupno")}</span>
            )}
          </div>
        </div>
        
        <div className="flex items-center gap-1 sm:gap-2 shrink-0">
          <ReportModal targetId={otherUser.id} targetType="USER" />
          <BlockButton userId={otherUser.id} isInitiallyBlocked={isBlockedByMe} />
        </div>
      </div>

      <ChatRoom 
        chatId={id} 
        currentUserId={session.user.id} 
        initialMessages={messages || []}
        b2bOffers={b2bOffers || []}
        listing={listing}
        isBlocked={isBlocked}
      />
    </div>
  );
}

"use client"

import { useState, useEffect } from "react"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { MessageSquare, Search, Loader2 } from "lucide-react"
import { createClient } from "@/lib/supabase/client"
import { useTranslations } from "next-intl";

export function ChatList({ chats: initialChats, currentUserId }: { chats: any[], currentUserId: string }) {
    const t = useTranslations();
  const [search, setSearch] = useState("")
  const [chats, setChats] = useState(initialChats)
  const [page, setPage] = useState(1)
  const [loading, setLoading] = useState(false)
  const [hasMore, setHasMore] = useState(initialChats.length === 50)
  const pathname = usePathname()
  const supabase = createClient()

  const loadMore = async () => {
    if (loading || !hasMore) return
    setLoading(true)
    const nextOffset = page * 50
    const { data } = await supabase.rpc("get_chats_with_unread", { p_limit: 50, p_offset: nextOffset })
    if (data && data.length > 0) {
      setChats(prev => [...prev, ...data])
      setPage(p => p + 1)
      if (data.length < 50) setHasMore(false)
    } else {
      setHasMore(false)
    }
    setLoading(false)
  }

  const filtered = chats.filter((chat) => {
    if (!search) return true
    const isBuyer = chat.buyer_id === currentUserId
    const otherUserName = isBuyer ? chat.seller_name : chat.buyer_name
    const listingTitle = chat.listing_title || ""
    const lastMsg = chat.last_message_content || ""
    
    const q = search.toLowerCase()
    return (otherUserName?.toLowerCase().includes(q) || 
            listingTitle.toLowerCase().includes(q) || 
            lastMsg.toLowerCase().includes(q))
  })

  return (
    <div className="flex flex-col h-full bg-background border-r">
      <div className="p-4 border-b bg-background sticky top-0 z-10 shrink-0">
        <h1 className="text-2xl font-bold tracking-tight mb-4">{t("soobscheniya")}</h1>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <input
            type="text"
            placeholder={t("poisk_po_chatam")}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-9 pr-4 py-2 bg-muted/50 focus:bg-background border rounded-xl text-sm transition-colors focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary"
          />
        </div>
      </div>

      <div className="flex-1 overflow-y-auto min-h-0 pb-16">
        {!chats || chats.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-6 text-muted-foreground">
            <MessageSquare className="w-12 h-12 mb-4 opacity-20" />
            <p className="text-sm">{t("u_vas_poka_net_1")}</p>
            <Link href="/catalog" className="text-sm text-primary font-medium mt-2 hover:underline">
              {t("nayti_tovar")}</Link>
          </div>
        ) : filtered.length === 0 ? (
          <div className="p-6 text-center text-sm text-muted-foreground">
            {t("nichego_ne_naydeno")}</div>
        ) : (
          <div className="divide-y divide-border/50">
            {filtered.map((chat) => {
              const isBuyer = chat.buyer_id === currentUserId
              const otherUserName = isBuyer ? chat.seller_name : chat.buyer_name
              const otherUserAvatar = isBuyer ? chat.seller_avatar : chat.buyer_avatar
              
              const listingTitle = chat.listing_title || "Товар удален"
              const listingImage = chat.listing_image || "/placeholder.png"
              
              const isActive = pathname === `/messages/${chat.id}`

              return (
                <Link 
                  key={chat.id} 
                  href={`/messages/${chat.id}`}
                  className={`flex gap-3.5 p-4 transition-colors outline-none relative group ${
                    isActive ? 'bg-primary/5' : 'hover:bg-muted/50 focus:bg-muted/50'
                  }`}
                >
                  {isActive && (
                    <div className="absolute left-0 top-0 bottom-0 w-1 bg-primary rounded-r-full" />
                  )}

                  <div className="shrink-0 relative">
                    <div className="w-14 h-14 rounded-xl overflow-hidden shadow-sm">
                      <img src={listingImage} alt={listingTitle} className="w-full h-full object-cover" />
                    </div>
                    <div className="absolute -bottom-1.5 -right-1.5 w-6 h-6 rounded-full border-[2.5px] border-background bg-muted flex items-center justify-center overflow-hidden text-[10px] font-bold text-muted-foreground shadow-sm">
                      {otherUserAvatar ? (
                        <img src={otherUserAvatar} className="w-full h-full object-cover" />
                      ) : (
                        otherUserName?.charAt(0) || "U"
                      )}
                    </div>
                  </div>

                  <div className="flex-1 min-w-0 flex flex-col py-0.5">
                    <div className="flex items-center justify-between gap-2 mb-1">
                      <h3 className="font-semibold text-[15px] truncate text-foreground">{otherUserName}</h3>
                      {chat.last_message_created_at && (
                        <span className={`text-[11px] whitespace-nowrap ${chat.unread_count > 0 ? 'font-medium text-primary' : 'text-muted-foreground'}`}>
                          {new Date(chat.last_message_created_at).toLocaleDateString("ru-RU", { day: "numeric", month: "short" })}
                        </span>
                      )}
                    </div>
                    
                    <p className="text-[13px] font-medium text-foreground/80 truncate mb-1.5">{listingTitle}</p>
                    
                    <div className="flex items-center justify-between gap-3">
                      {chat.last_message_content ? (
                        <p className={`text-[13px] truncate ${chat.unread_count > 0 ? 'font-medium text-foreground' : 'text-muted-foreground'}`}>
                          {chat.last_message_sender_id === currentUserId && <span className="text-primary mr-1">{t("vy")}</span>}
                          {chat.last_message_content}
                        </p>
                      ) : (
                        <p className="text-[13px] text-muted-foreground/70 italic">{t("net_soobscheniy")}</p>
                      )}

                      {chat.unread_count > 0 && (
                        <span className="bg-primary text-primary-foreground text-[10px] font-bold px-1.5 py-0.5 rounded-full shrink-0 min-w-[1.25rem] text-center shadow-sm">
                          {chat.unread_count}
                        </span>
                      )}
                    </div>
                  </div>
                </Link>
              );
            })}

            {hasMore && !search && (
              <div className="p-4 flex justify-center">
                <button 
                  onClick={loadMore} 
                  disabled={loading}
                  className="text-sm text-primary hover:underline flex items-center gap-2"
                >
                  {loading && <Loader2 className="w-4 h-4 animate-spin" />}
                  {t("zagruzit_esche")}</button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import { redirect } from "next/navigation"
import { createClient } from "@/lib/supabase/server"
import { MyListingsClient } from "@/features/my-listings/components/my-listings-client"
import { useTranslations } from "next-intl";
import { getTranslations } from "next-intl/server";

export const metadata = {
  title: "Мои объявления | BazarGo",
}

export default async function MyListingsPage(props: { searchParams: Promise<{ [key: string]: string | undefined }> }) {
    const t = await getTranslations();
  const searchParams = await props.searchParams;
  const supabase = await createClient()
  const { data: { session } } = await supabase.auth.getSession()

  if (!session) {
    redirect("/login?redirect_to=/my-listings")
  }

  const page = parseInt(searchParams.page || "1", 10)
  const limit = 20
  const from = (page - 1) * limit
  const to = from + limit - 1

  let query = supabase
    .from("listings")
    .select(`
      *,
      listing_images(url, order_index)
    `, { count: "exact" })
    .eq("seller_id", session.user.id)
    .order("created_at", { ascending: false })

  const status = searchParams.status || "all"
  if (status !== "all") {
    query = query.eq("status", status.toUpperCase())
  }

  query = query.range(from, to)

  const { data: listings, count, error } = await query

  if (error) {
    console.error("Failed to fetch my listings:", error)
  }
  
  const totalPages = count ? Math.ceil(count / limit) : 1

  return (
    <div className="container mx-auto px-4 py-8 max-w-5xl">
      <div className="flex items-center justify-between mb-8">
        <h1 className="text-3xl font-bold tracking-tight">{t("moi_obyavleniya")}</h1>
        <a href="/profile" className="text-sm font-medium text-muted-foreground hover:text-foreground hidden sm:block">
          {t("vernutsya_v_profil")}</a>
      </div>
      <MyListingsClient listings={listings || []} status={status} page={page} totalPages={totalPages} totalCount={count || 0} />
    </div>
  );
}

