      .select("*")
      .eq("id", editId)
      .eq("seller_id", session.user.id)
      .single()

    if (listing) {
      initialData = {
        id: listing.id,
        type: listing.listing_type,
        title: listing.title,
        categoryId: listing.category_id,
        price: listing.price,
        condition: listing.condition,
        description: listing.description,
        quantity: listing.quantity,
        region: listing.region,
        city: listing.city,
        deliveryMethods: listing.delivery_methods,
        showPhone: listing.show_phone,
        images: [] // images are not loaded as File objects
      }
    }
  }

  return (
    <div className="min-h-screen bg-background">
      <SellFlow categories={categories} userStore={store} initialData={initialData} requestedStoreId={requestedStoreId} />
    </div>
  )
}

