import { revalidatePath } from "next/cache"

export async function updateOrderStatus(orderId: string, newStatus: string) {
  const supabase = await createClient()
  const { data: { session } } = await supabase.auth.getSession()

  if (!session) return { error: "Необходима авторизация" }

  let error = null
  let data = null

  if (newStatus === "CONFIRMED") {
    const res = await supabase.rpc("confirm_order", { order_id_param: orderId })
    error = res.error
    data = res.data
  } else if (newStatus === "REJECTED") {
    const res = await supabase.rpc("reject_order", { order_id_param: orderId })
    error = res.error
    data = res.data
  } else if (newStatus === "CANCELLED") {
    const res = await supabase.rpc("cancel_order", { order_id_param: orderId })
    error = res.error
    data = res.data
  } else {
    return { error: "Недопустимый статус" }
  }

  if (error) {
    console.error("RPC error:", error)
    return { error: error.message || "Ошибка при обновлении статуса" }
  }

  revalidatePath(`/orders/${orderId}`)
  revalidatePath(`/seller/orders/${orderId}`)
  revalidatePath("/orders")
  revalidatePath("/seller/orders")
  return { success: true }
}

export async function completeOrder(orderId: string) {
  const supabase = await createClient()
  const { data: { session } } = await supabase.auth.getSession()

  if (!session) return { error: "Необходима авторизация" }

  // Call the atomic RPC function
  const { data, error } = await supabase
    .rpc("complete_order", {
      order_id_param: orderId
    })

  if (error) {
    console.error("RPC complete_order error:", error)
    return { error: error.message || "Ошибка при завершении сделки" }
  }

  revalidatePath(`/orders/${orderId}`)
  revalidatePath(`/seller/orders/${orderId}`)
  revalidatePath("/orders")
  revalidatePath("/seller/orders")
  return { success: true }
}

"use server"

import { createClient } from "@/lib/supabase/server"
import { revalidatePath } from "next/cache"
import { v4 as uuidv4 } from 'uuid'

export async function publishListing(formData: FormData) {
  try {
    const supabase = await createClient()
    if (!supabase) throw new Error("Supabase is not configured")

    const { data: { session }, error: authError } = await supabase.auth.getSession()
    if (authError || !session) throw new Error("Не авторизован")

    // 0. Ensure profile exists (self-healing for users created before DB migrations)
    const { data: profile } = await supabase.from("profiles").select("id").eq("id", session.user.id).single()
    if (!profile) {
      const { error: profileError } = await supabase.from("profiles").insert({
        id: session.user.id,
        phone: session.user.phone,
        email: session.user.email,
        full_name: session.user.user_metadata?.full_name || "Пользователь"
      })
      if (profileError) console.error("Self-healing profile creation failed:", profileError)
    }

    // 0. Server-side validation
    const id = formData.get("id") as string | null
    const type = formData.get("type") as string
    const title = formData.get("title") as string
    const categoryId = formData.get("categoryId") as string
    const priceStr = formData.get("price") as string
    const condition = formData.get("condition") as string
    const description = formData.get("description") as string
    const quantityStr = formData.get("quantity") as string
    const region = formData.get("region") as string
    const city = formData.get("city") as string
    const showPhone = formData.get("showPhone") === "true"

    let deliveryMethods = []
    try {
      deliveryMethods = JSON.parse(formData.get("deliveryMethods") as string || "[]")
    } catch (e) {}

    const { z } = await import("zod")
    const schema = z.object({
      title: z.string().min(5, "Слишком короткое название").max(200, "Слишком длинное название"),
      categoryId: z.string().uuid("Некорректная категория"),
      price: z.number().min(0, "Некорректная цена").max(1000000000, "Слишком большая цена"),
      quantity: z.number().min(0, "Количество не может быть отрицательным").max(100000, "Слишком большое количество"),
      region: z.string().min(2, "Регион обязателен").max(100),
      city: z.string().min(2, "Город обязателен").max(100),
      description: z.string().max(5000, "Слишком длинное описание"),
      condition: z.enum(["NEW", "USED_LIKE_NEW", "USED_GOOD", "USED_FAIR", "FOR_PARTS"]),
      type: z.enum(["SINGLE", "INVENTORY"])
    })

    const parsed = schema.safeParse({
      title,
      categoryId,
      price: parseFloat(priceStr),
      quantity: quantityStr ? parseInt(quantityStr) : 1,
      region,
      city,
      description: description || "",
      condition,
      type
    })

    if (!parsed.success) {
      throw new Error(parsed.error.errors[0].message)
    }

    const price = parsed.data.price
    const quantity = parsed.data.quantity

    // Rate Limit: 10 listings per hour
    if (!id) {
      const { data: rateOk, error: rateErr } = await supabase.rpc("check_rate_limit", { 
        p_action_type: "create_listing", 
        p_limit: 10, 
        p_window_minutes: 60 
      })
      if (rateErr) console.error("Rate limit check error:", rateErr)
      if (rateOk === false) throw new Error("Превышен лимит создания объявлений. Попробуйте позже.")
    }

    const publishAsStore = formData.get("publishAsStore") === "true"

    let storeId = null
    // If edit, we should preserve the store_id if it was published as store
    // WAIT, what if a user edits someone else's listing?
    // We MUST enforce ownership check on existing listings!
    if (id) {
      const { data: existing } = await supabase.from("listings").select("store_id, seller_id").eq("id", id).single()
      if (!existing || existing.seller_id !== session.user.id) {
         throw new Error("У вас нет прав для редактирования этого объявления")
      }
      storeId = existing.store_id
    } else if (publishAsStore && type === "INVENTORY") {
      const { data: store } = await supabase
        .from("stores")
        .select("id")
        .eq("owner_id", session.user.id)
        .eq("status", "APPROVED")
        .single()
      if (store) storeId = store.id
    }

    const finalQuantity = type === "INVENTORY" ? quantity : 1;
    const finalStatus = finalQuantity === 0 ? "OUT_OF_STOCK" : "ACTIVE";

    const isB2b = formData.get("isB2b") === "true";
    const wholesalePriceStr = formData.get("wholesalePrice");
    const minOrderQuantityStr = formData.get("minOrderQuantity");
    const wholesalePrice = wholesalePriceStr ? parseFloat(wholesalePriceStr.toString()) : null;
    const minOrderQuantity = minOrderQuantityStr ? parseInt(minOrderQuantityStr.toString(), 10) : 1;

    const payload = {
      seller_id: session.user.id,
      store_id: storeId,
      title,
      description,
      category_id: categoryId,
      price,
      condition,
      quantity: finalQuantity,
      listing_type: type,
      region,
      city,
      delivery_methods: deliveryMethods,
      show_phone: showPhone,
      status: finalStatus,
      is_b2b: isB2b,
      wholesale_price: wholesalePrice,
      min_order_quantity: minOrderQuantity
    }

    // 1. Create or Update listing record
    let listingResponse;
    if (id) {
      listingResponse = await supabase.from("listings").update(payload).eq("id", id).eq("seller_id", session.user.id).select("id").single()
    } else {
      listingResponse = await supabase.from("listings").insert(payload).select("id").single()
    }

    const { data: listing, error: listingError } = listingResponse;

    if (listingError) {
      throw new Error(`Ошибка базы данных: ${listingError.message} (код ${listingError.code})`)
    }

    const listingId = listing.id

    // 2. Upload images
    const imageUrls: string[] = []
    const uploadedPaths: string[] = []
    let uploadFailed = false

    const { data: existingImages } = await supabase.from("listing_images").select("id").eq("listing_id", listingId)
    let totalImages = existingImages ? existingImages.length : 0

    // Import at top level or inline (Next.js server actions handle this fine, but let's dynamically import to avoid breaking client boundaries if any, though it's a server file)
    const { validateImage, MAX_LISTING_IMAGE_SIZE } = await import('@/lib/image-validation');

    for (let i = 0; i < 10; i++) {
      const file = formData.get(`image_${i}`) as File | null
      if (file && file.size > 0) {
        // Validate
        const validation = await validateImage(file, MAX_LISTING_IMAGE_SIZE);
        if (!validation.valid || !validation.buffer || !validation.format || !validation.mime) {
           uploadFailed = true
           // We could throw here, but let's break and let the rollback happen
           throw new Error(`Ошибка изображения: ${validation.error}`);
        }

        const fileName = `${session.user.id}/${listingId}/${uuidv4()}.${validation.format}`

        const { error: uploadError } = await supabase
          .storage
          .from("product-images")
          .upload(fileName, validation.buffer, {
             contentType: validation.mime
          })

        if (uploadError) {
          uploadFailed = true
          break
        } else {
          uploadedPaths.push(fileName)
          const { data: publicUrlData } = supabase.storage.from("product-images").getPublicUrl(fileName)
          imageUrls.push(publicUrlData.publicUrl)
        }
      }
    }

    if (uploadFailed) {
      if (uploadedPaths.length > 0) {
        await supabase.storage.from("product-images").remove(uploadedPaths)
      }
      if (!id) {
        await supabase.from("listings").delete().eq("id", listingId)
      }
      throw new Error("Ошибка при загрузке изображений. Попробуйте еще раз.")
    }

    // 3. Insert listing images
    if (imageUrls.length > 0) {
      let oldPathsToDelete: string[] = []

      // If it's an edit, we assume a full replacement since the frontend forces re-upload
      if (id && existingImages && existingImages.length > 0) {
        // Extract paths from old URLs to delete from storage AFTER successful DB update
        const { data: oldImages } = await supabase.from("listing_images").select("url").eq("listing_id", listingId);
        if (oldImages) {
          oldPathsToDelete = oldImages.map((img: any) => {
             const parts = img.url.split("/product-images/");
             return parts.length > 1 ? parts[1] : null;
          }).filter(Boolean);
        }
        totalImages = 0; // We will replace them
      }

      if (totalImages + imageUrls.length > 10) {
        if (uploadedPaths.length > 0) {
          await supabase.storage.from("product-images").remove(uploadedPaths)
        }
        throw new Error("Максимальное количество изображений - 10")
      }

      const imageRecords = imageUrls.map((url, index) => ({
        listing_id: listingId,
        url,
        order_index: totalImages + index
      }))

      // First delete old DB records if editing
      if (id && oldPathsToDelete.length > 0) {
        const { error: deleteError } = await supabase.from("listing_images").delete().eq("listing_id", listingId);
        if (deleteError) {
          // If delete fails, new images are orphans. Remove them.
          if (uploadedPaths.length > 0) {
            await supabase.storage.from("product-images").remove(uploadedPaths)
          }
          throw new Error("Ошибка при обновлении изображений (удаление старых)")
        }
      }

      // Then insert new DB records
      const { error: imageError } = await supabase
        .from("listing_images")
        .insert(imageRecords)

      if (imageError) {
        // If insert fails, we already deleted old DB records (if edit). This is a partial DB failure.
        // However, we remove the newly uploaded storage files so we don't leak storage.
        // Old files are left in storage (orphaned from DB, but safe).
        if (uploadedPaths.length > 0) {
          await supabase.storage.from("product-images").remove(uploadedPaths)
        }
        if (!id) await supabase.from("listings").delete().eq("id", listingId)
        throw new Error("Ошибка сохранения новых изображений")
      }

      // FINALLY: Only if DB insert succeeds, safely delete old files from storage
      if (oldPathsToDelete.length > 0) {
        // Fire and forget, or await. If this fails, it's just an orphan file, no data loss.
        await supabase.storage.from("product-images").remove(oldPathsToDelete).catch(console.error);
      }

      totalImages += imageUrls.length
    }

    if (totalImages === 0) {
      if (uploadedPaths.length > 0) {
        await supabase.storage.from("product-images").remove(uploadedPaths)
      }
      if (!id) await supabase.from("listings").delete().eq("id", listingId)
      throw new Error("Необходимо загрузить хотя бы одно фото")
    }

    revalidatePath("/")
    revalidatePath("/profile")
    revalidatePath("/my-listings")
    revalidatePath("/catalog")

    return { success: true, listingId }
  } catch (err: any) {
    console.error("Publish listing error:", err)
    return { success: false, error: err.message || "Unknown error" }
  }
}

"use server"

import { createClient } from "@/lib/supabase/server"
import { revalidatePath } from "next/cache"

// Utility to generate a basic slug
function generateSlug(text: string) {
  const cyrillicToLatinMap: Record<string, string> = {
    'а': 'a', 'б': 'b', 'в': 'v', 'г': 'g', 'д': 'd', 'е': 'e', 'ё': 'yo', 'ж': 'zh',
    'з': 'z', 'и': 'i', 'й': 'j', 'к': 'k', 'л': 'l', 'м': 'm', 'н': 'n', 'о': 'o',
    'п': 'p', 'р': 'r', 'с': 's', 'т': 't', 'у': 'u', 'ф': 'f', 'х': 'h', 'ц': 'c',
    'ч': 'ch', 'ш': 'sh', 'щ': 'shch', 'ъ': '', 'ы': 'y', 'ь': '', 'э': 'e', 'ю': 'yu',
    'я': 'ya'
  };

  const transliterated = text
    .toString()
    .toLowerCase()
    .split('')
    .map(char => cyrillicToLatinMap[char] || char)
    .join('');

  return transliterated
    .trim()
    .replace(/\s+/g, '-')
    .replace(/[^\w\-]+/g, '')
    .replace(/\-\-+/g, '-')
    .replace(/^-+/, '')
    .replace(/-+$/, '');
}

export async function createStore(formData: FormData) {
  const supabase = await createClient()
  const { data: { session } } = await supabase.auth.getSession()

  if (!session) {
    return { error: "Необходима авторизация" }
  }

  const name = formData.get("name") as string
  const description = formData.get("description") as string
  const categoryId = formData.get("categoryId") as string
  const city = formData.get("city") as string
  const phone = formData.get("phone") as string
  const email = formData.get("email") as string
  const logo = formData.get("logo") as File | null

  if (!name || !categoryId || !city) {
    return { error: "Заполните обязательные поля" }
  }

  let slug = generateSlug(name)
  if (!slug) slug = `store-${Date.now()}`

  // Make slug unique
  const { data: existing } = await supabase.from("stores").select("id").eq("slug", slug).maybeSingle()
  if (existing) {
    slug = `${slug}-${Math.floor(Math.random() * 1000)}`
  }

  let logoUrl = null
  let uploadedFileName: string | null = null

  if (logo && logo.size > 0) {
    const { validateImage, MAX_STORE_LOGO_SIZE } = await import('@/lib/image-validation');
    const validation = await validateImage(logo, MAX_STORE_LOGO_SIZE);

    if (!validation.valid || !validation.buffer || !validation.format || !validation.mime) {
      return { error: `Ошибка изображения: ${validation.error}` }
    }

    const fileName = `${session.user.id}/${Date.now()}.${validation.format}`
    const { data: uploadData, error: uploadError } = await supabase.storage
      .from('store-images')
      .upload(fileName, validation.buffer, {
        contentType: validation.mime
      })

    if (uploadError) {
      console.error("Upload error:", uploadError)
      return { error: "Ошибка загрузки логотипа" }
    }

    const { data: { publicUrl } } = supabase.storage
      .from('store-images')
      .getPublicUrl(fileName)

    logoUrl = publicUrl
    uploadedFileName = fileName
  }

  const { data: store, error } = await supabase
    .from("stores")
    .insert({
      owner_id: session.user.id,
      name,
      slug,
      description,
      category_id: categoryId,
      city,
      phone,
      email: email || null,
      logo_url: logoUrl,
      status: "PENDING"
    })
    .select()
    .single()

  if (error) {
    console.error("Create store error:", error)
    // Rollback the uploaded file
    if (uploadedFileName) {
      const { error: removeError } = await supabase.storage.from('store-images').remove([uploadedFileName])
      if (removeError) {
        console.error("Rollback failed for store-images (orphan file):", removeError)
      }
    }

    if (error.code === '23505') {
      return { error: "У вас уже есть магазин" } // Unique constraint error if we added one (though we didn't, but logic prevents multiple via checking before call)
    }
    return { error: "Ошибка при создании магазина. Пожалуйста, попробуйте еще раз." }
  }

  revalidatePath("/stores")
  revalidatePath("/my-store")
  return { success: true, store }
}

export async function updateStore(storeId: string, formData: FormData) {
  const supabase = await createClient()
  const { data: { session } } = await supabase.auth.getSession()

  if (!session) {
    return { error: "Необходима авторизация" }
  }

  // 1. Verify ownership and fetch existing logo URL
  const { data: existingStore } = await supabase
    .from("stores")
    .select("owner_id, logo_url")
    .eq("id", storeId)
    .single()

  if (!existingStore || existingStore.owner_id !== session.user.id) {
    return { error: "У вас нет прав для редактирования этого магазина" }
  }

  const oldLogoUrl = existingStore.logo_url;

  const name = formData.get("name") as string
  const description = formData.get("description") as string
  const categoryId = formData.get("categoryId") as string
  const city = formData.get("city") as string
  const phone = formData.get("phone") as string
  const email = formData.get("email") as string
  const logo = formData.get("logo") as File | null

  if (!name || !categoryId || !city) {
    return { error: "Заполните обязательные поля" }
  }

  const updates: any = {
    name,
    description,
    category_id: categoryId,
    city,
    phone,
    email: email || null,
    updated_at: new Date().toISOString()
  }

  let uploadedFileName: string | null = null;

  if (logo && logo.size > 0) {
    const { validateImage, MAX_STORE_LOGO_SIZE } = await import('@/lib/image-validation');
    const validation = await validateImage(logo, MAX_STORE_LOGO_SIZE);

    if (!validation.valid || !validation.buffer || !validation.format || !validation.mime) {
      return { error: `Ошибка изображения: ${validation.error}` }
    }

    const fileName = `${session.user.id}/${Date.now()}.${validation.format}`
    const { data: uploadData, error: uploadError } = await supabase.storage
      .from('store-images')
      .upload(fileName, validation.buffer, {
        contentType: validation.mime
      })

    if (uploadError) {
      console.error("Upload error:", uploadError)
      return { error: "Ошибка загрузки логотипа" }
    }

    const { data: { publicUrl } } = supabase.storage
      .from('store-images')
      .getPublicUrl(fileName)

    updates.logo_url = publicUrl
    uploadedFileName = fileName
  }

  const { error } = await supabase
    .from("stores")
    .update(updates)
    .eq("id", storeId)
    .eq("owner_id", session.user.id) // Security check

  if (error) {
    console.error("Update store error:", error)
    if (uploadedFileName) {
      const { error: removeError } = await supabase.storage.from('store-images').remove([uploadedFileName])
      if (removeError) console.error("Rollback failed for new store logo:", removeError)
    }
    return { error: "Ошибка при обновлении магазина. Пожалуйста, попробуйте еще раз." }
  }

  // Cleanup old logo if update was successful and a new logo was uploaded
  if (uploadedFileName && oldLogoUrl) {
    try {
      const urlParts = oldLogoUrl.split('store-images/');
      if (urlParts.length === 2) {
        const oldPath = decodeURIComponent(urlParts[1]);
        // Security check: ensure the path actually belongs to the user before deleting
        if (oldPath.startsWith(`${session.user.id}/`)) {
          const { error: removeError } = await supabase.storage.from('store-images').remove([oldPath])
          if (removeError) console.error("Failed to cleanup old store logo:", removeError)
        }
      }
    } catch (cleanupError) {
      console.error("Old logo cleanup exception:", cleanupError)
    }
  }

  revalidatePath("/stores")
  revalidatePath("/my-store")
  return { success: true }
}

export async function toggleFollowStore(storeId: string) {
  const supabase = await createClient()
  const { data: { session } } = await supabase.auth.getSession()

  if (!session) {
    return { error: "Необходима авторизация" }
  }

  // Check if following
  const { data: existing } = await supabase
    .from("follows")
    .select("*")
    .eq("follower_id", session.user.id)
    .eq("followed_store_id", storeId)
    .maybeSingle()

  if (existing) {
    // Unfollow
    const { error: deleteError } = await supabase
      .from("follows")
      .delete()
      .eq("follower_id", session.user.id)
      .eq("followed_store_id", storeId)

    if (deleteError) return { success: false, error: "Ошибка отписки" }
  } else {
    // Follow
    const { error: insertError } = await supabase
      .from("follows")
      .insert({
        follower_id: session.user.id,
        followed_store_id: storeId
      })

    if (insertError) return { success: false, error: "Ошибка подписки" }
  }

  revalidatePath(`/store/[slug]`, "page")
  revalidatePath(`/stores`)
  return { success: true, isFollowing: !existing }
}

