  );
}

"use client"

import { useState } from "react"
import { blockUserAction, unblockUserAction, changeUserRoleAction } from "@/features/admin/actions"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { toast } from "sonner"
import { Loader2, ShieldOff, ShieldAlert, ShieldCheck } from "lucide-react"
import { useTranslations } from "next-intl";

type Profile = {
  id: string
  full_name: string | null
  role: string
  is_banned: boolean
}

export function UserActions({ user }: { user: Profile }) {
  const t = useTranslations();
  const [isPending, setIsPending] = useState(false)
  const [reason, setReason] = useState("")
  const [showReason, setShowReason] = useState(false)
  const [showRoleSelect, setShowRoleSelect] = useState(false)
  const [selectedRole, setSelectedRole] = useState(user.role)

  const handleAction = async () => {
    if (!reason.trim()) {
      toast.error("Пожалуйста, укажите причину")
      return
    }

    setIsPending(true)
    try {
      if (showRoleSelect) {
        await changeUserRoleAction(user.id, selectedRole, reason)
        toast.success("Роль изменена")
        setShowRoleSelect(false)
      } else {
        if (user.is_banned) {
          await unblockUserAction(user.id, reason)
          toast.success("Пользователь разблокирован")
        } else {
          await blockUserAction(user.id, reason)
          toast.success("Пользователь заблокирован")
        }
      }
      setShowReason(false)
      setReason("")
    } catch (e: any) {
      toast.error(e.message || "Произошла ошибка")
    } finally {
      setIsPending(false)
    }
  }

  if (showReason) {
    return (
      <div className="flex flex-col gap-2 bg-muted/50 p-2 rounded-md border text-left min-w-[200px]">
        {showRoleSelect && (
          <select 
            className="border rounded-md px-2 py-1 text-sm bg-background" 
            value={selectedRole} 
            onChange={e => setSelectedRole(e.target.value)}
            disabled={isPending}
          >
            <option value="USER">User</option>
            <option value="MODERATOR">Moderator</option>
            <option value="SUPPORT">Support</option>
            <option value="ADMIN">Admin</option>
            <option value="SUPER_ADMIN">Super Admin</option>
          </select>
        )}
        <Input 
          size={1} 
          className="w-full h-8 text-xs" 
          placeholder={t("prichina")} 
          value={reason} 
          onChange={(e) => setReason(e.target.value)}
          disabled={isPending}
        />
        <div className="flex justify-end gap-2 mt-1">
          <Button size="sm" className="h-7 text-xs" variant="ghost" disabled={isPending} onClick={() => { setShowReason(false); setShowRoleSelect(false) }}>
            {t("otmena")}
          </Button>
          <Button size="sm" className="h-7 text-xs" variant="default" disabled={isPending} onClick={handleAction}>
            {isPending ? <Loader2 className="w-3 h-3 animate-spin" /> : "OK"}
          </Button>
        </div>
      </div>
    );
  }

  if (user.role === 'SUPER_ADMIN') {
    return <span className="text-xs text-muted-foreground block py-1">{t("neizmenyaemyy")}</span>;
  }

  return (
    <div className="flex flex-col sm:flex-row gap-2 justify-end">
      <Button 
        size="sm" 
        variant="outline" 
        className="h-8 text-xs"
        onClick={() => { setShowReason(true); setShowRoleSelect(true) }}
      >
        <ShieldCheck className="w-3 h-3 mr-1" /> Изменить роль
      </Button>
      <Button 
        size="sm" 
        variant={user.is_banned ? "outline" : "destructive"} 
        className="h-8 text-xs"
        onClick={() => setShowReason(true)}
      >
        {user.is_banned ? (
          <><ShieldOff className="w-3 h-3 mr-1" /> {t("razblokirovat")}</>
        ) : (
          <><ShieldAlert className="w-3 h-3 mr-1" /> {t("zablokirovat")}</>
        )}
      </Button>
    </div>
  );
}

"use client"

import { useState, useEffect } from "react"
import { useRouter, useSearchParams } from "next/navigation"
import { createClient } from "@/lib/supabase/client"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Mail, Phone as PhoneIcon } from "lucide-react"
import { useTranslations } from "next-intl";

export function PhoneAuthForm() {
    const t = useTranslations();
  const [authMethod, setAuthMethod] = useState<"email" | "phone">("email")
  const [step, setStep] = useState<"input" | "otp">("input")
  const [name, setName] = useState("")
  const [identifier, setIdentifier] = useState("") // email or phone
  const [otp, setOtp] = useState("")
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [isOtpFocused, setIsOtpFocused] = useState(false)
  
  const [countdown, setCountdown] = useState(0)

  const router = useRouter()
  const searchParams = useSearchParams()
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
  const supabase = supabaseUrl ? createClient() : null

  const otpLength = authMethod === "email" ? 8 : 6;

  const handleOtpChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value.replace(/[^0-9]/g, "");
    if (val.length <= otpLength) {
      setOtp(val);
    } else {
      setOtp(val.slice(0, otpLength));
    }
  }

  useEffect(() => {
    let timer: NodeJS.Timeout
    if (countdown > 0) {
      timer = setTimeout(() => setCountdown(countdown - 1), 1000)
    }
    return () => clearTimeout(timer)
  }, [countdown])

  const handleSendOtp = async (e?: React.FormEvent) => {
    if (e) e.preventDefault()
    setError(null)
    
    if (!supabase) {
      setError("ОШИБКА: Файл .env.local не настроен. Ключи Supabase отсутствуют.")
      return
    }

    if (!name || name.trim().length < 2) {
      setError("Пожалуйста, введите ваше имя")
      return
    }

    if (!identifier) {
      setError(authMethod === "email" ? "Введите email" : "Введите номер телефона")
      return
    }

    setIsLoading(true)

    try {
      let authError;
      
      if (authMethod === "email") {
        const rawRedirect = searchParams.get("redirect_to")
        let nextParam = "/profile"
        if (rawRedirect && rawRedirect.startsWith("/") && !rawRedirect.startsWith("//")) {
          nextParam = rawRedirect
        }

        const { error } = await supabase.auth.signInWithOtp({
          email: identifier,
          options: {
            data: { full_name: name.trim() },
            emailRedirectTo: `${window.location.origin}/auth/callback?next=${encodeURIComponent(nextParam)}`
          }
        })
        authError = error
      } else {
        const { error } = await supabase.auth.signInWithOtp({
          phone: identifier,
          options: {
            data: { full_name: name.trim() }
          }
        })
        authError = error
      }

      if (authError) throw authError
      
      setStep("otp")
      setCountdown(60)
    } catch (err: any) {
      console.error("[AUTH_DIAGNOSTICS] signInWithOtp failed:", {
        message: err.message,
        name: err.name,
        status: err.status,
        code: err.code,
      });

      if (err.message?.includes("rate limit") || err.status === 429) {
        setError("Слишком много попыток. Попробуйте позже.")
      } else if (!process.env.NEXT_PUBLIC_SUPABASE_URL) {
        setError("ОШИБКА: Файл .env.local не настроен. Ключи Supabase отсутствуют.")
      } else if (err.message?.includes("Unsupported phone provider") || err.message?.includes("sms provider")) {
        setError("Вход по телефону пока недоступен: SMS-провайдер не настроен.")
      } else {
        setError(authMethod === "email" ? "Проверьте правильность email" : "Проверьте номер телефона")
      }
    } finally {
      setIsLoading(false)
    }
  }

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    
    if (!supabase) return

    if (!otp || otp.length < 4) {
      setError("Код введён неверно")
      return
    }

    setIsLoading(true)

    try {
      let data, authError;

      if (authMethod === "email") {
        const res = await supabase.auth.verifyOtp({
          email: identifier,
          token: otp,
          type: "email",
        })
        data = res.data
        authError = res.error
      } else {
        const res = await supabase.auth.verifyOtp({
          phone: identifier,
          token: otp,
          type: "sms",
        })
        data = res.data
        authError = res.error
      }

      if (authError) throw authError

      if (data?.session) {
        const rawRedirect = searchParams.get("redirect_to")
        let redirectTo = "/profile"
        if (rawRedirect && rawRedirect.startsWith("/") && !rawRedirect.startsWith("//")) {
          redirectTo = rawRedirect
        }
        router.push(redirectTo)
        router.refresh()
      }
    } catch (err: any) {
      console.error("[AUTH_DIAGNOSTICS] verifyOtp failed:", {
        message: err.message,
        name: err.name,
        status: err.status,
        code: err.code,
      });
      if (err.message?.includes("expired")) {
        setError("Код истёк")
      } else {
        setError("Код введён неверно")
      }
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="w-full max-w-sm mx-auto space-y-6">
      <div className="text-center space-y-2">
        <h1 className="text-2xl font-bold tracking-tight">{t("voyti_ili_zaregistrirovatsya")}</h1>
        <p className="text-sm text-muted-foreground">
          {step === "input" 
            ? "Продолжая, вы соглашаетесь с правилами BazarGo." 
            : `Код отправлен на ${identifier}`}
        </p>
      </div>

      {error && (
        <div className="p-3 text-sm text-destructive bg-destructive/10 rounded-xl text-center border border-destructive/20 font-medium">
          {error}
        </div>
      )}

      {step === "input" ? (
        <Tabs defaultValue="email" onValueChange={(v) => setAuthMethod(v as "email" | "phone")} className="w-full">
          <TabsList className="grid w-full grid-cols-2 mb-4 h-12 rounded-xl">
            <TabsTrigger value="email" className="rounded-lg gap-2 text-sm">
              <Mail className="w-4 h-4" /> Email
            </TabsTrigger>
            <TabsTrigger value="phone" className="rounded-lg gap-2 text-sm">
              <PhoneIcon className="w-4 h-4" /> {t("telefon")}</TabsTrigger>
          </TabsList>
          
          <form onSubmit={handleSendOtp} className="space-y-4">
            <div className="space-y-2 text-left">
              <Label htmlFor="name">{t("imya")}</Label>
              <Input
                id="name"
                type="text"
                placeholder={t("kak_k_vam_obraschatsya")}
                value={name}
                onChange={(e) => setName(e.target.value)}
                disabled={isLoading}
                required
                className="h-12 bg-muted/50 border-border"
              />
            </div>
            
            <div className="space-y-2 text-left">
              <Label htmlFor="identifier">
                {authMethod === "email" ? "Email адрес" : "Номер телефона"}
              </Label>
              <Input
                id="identifier"
                type={authMethod === "email" ? "email" : "tel"}
                placeholder={authMethod === "email" ? "example@email.com" : "+996 555 000 000"}
                value={identifier}
                onChange={(e) => setIdentifier(e.target.value)}
                disabled={isLoading}
                required
                className="h-12 bg-muted/50 border-border tracking-wider"
                dir="ltr"
              />
            </div>
            
            <Button type="submit" className="w-full h-12 text-base font-semibold shadow-sm rounded-xl" disabled={isLoading}>
              {isLoading ? "Отправка..." : "Получить код"}
            </Button>
          </form>
        </Tabs>
      ) : (
        <form onSubmit={handleVerifyOtp} className="space-y-4">
          <div className="space-y-2 text-left">
            <div className="flex items-center justify-between">
              <Label htmlFor="otp">{t("vvedite_kod")}</Label>
              <button 
                type="button" 
                onClick={() => {
                  setStep("input")
                  setOtp("")
                }}
                className="text-xs text-primary hover:underline font-medium"
              >
                {t("izmenit")}</button>
            </div>
            <div className="relative flex justify-between gap-1 sm:gap-2">
              <Input
                id="otp"
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                autoComplete="one-time-code"
                value={otp}
                onChange={handleOtpChange}
                onFocus={() => setIsOtpFocused(true)}
                onBlur={() => setIsOtpFocused(false)}
                disabled={isLoading}
                required
                className="absolute inset-0 w-full h-full opacity-0 z-10 cursor-text"
                maxLength={otpLength}
                aria-label={`${otpLength}-значный код`}
              />
              <div className="flex w-full justify-between gap-1 sm:gap-2" aria-hidden="true">
                {Array.from({ length: otpLength }).map((_, i) => {
                  const char = otp[i] || "";
                  const isFocused = isOtpFocused && (otp.length === i || (otp.length === otpLength && i === otpLength - 1));
                  return (
                    <div 
                      key={i} 
                      className={`flex-1 h-12 sm:h-14 flex items-center justify-center border-2 rounded-xl text-lg sm:text-xl font-bold transition-all bg-muted/30 ${char ? 'border-primary text-primary' : 'border-border'} ${isFocused ? 'ring-2 ring-primary/50' : ''}`}
                    >
                      {char}
                    </div>
                  )
                })}
              </div>
            </div>
          </div>
          
          <Button type="submit" className="w-full h-12 text-base font-semibold shadow-sm rounded-xl" disabled={isLoading || otp.length !== otpLength}>
            {isLoading ? "Проверка..." : "Подтвердить"}
          </Button>

          <div className="pt-4 text-center">
            {countdown > 0 ? (
              <p className="text-sm text-muted-foreground">
                {t("otpravit_kod_povtorno_cherez")}{countdown} {t("sek")}</p>
            ) : (
              <button 
                type="button"
                onClick={() => handleSendOtp()}
                className="text-sm text-primary font-medium hover:underline"
                disabled={isLoading}
              >
                {t("otpravit_kod_povtorno")}</button>
            )}
          </div>
        </form>
      )}
    </div>
  );
}

"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { Handshake } from "lucide-react"
import { useRouter } from "next/navigation"
import { createClient } from "@/lib/supabase/client"

interface CreateOfferProps {
  listingId: string;
  minOrderQuantity: number;
  suggestedPrice: number;
  sellerId: string;
  currentUserId?: string;
}

export function CreateB2BOfferModal({ listingId, minOrderQuantity, suggestedPrice, sellerId, currentUserId }: CreateOfferProps) {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const [quantity, setQuantity] = useState(minOrderQuantity)
  const [price, setPrice] = useState(suggestedPrice)
  const [message, setMessage] = useState("")

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!currentUserId) {
      router.push(`/login?next=/product/${listingId}`)
      return
    }

    setLoading(true)
    setError(null)

    try {
      const supabase = createClient()
      const { data, error: rpcError } = await supabase.rpc("create_b2b_offer", {
        p_listing_id: listingId,
        p_quantity: quantity,
        p_price: price,
        p_message: message
      })

      if (rpcError) throw rpcError;

      setOpen(false)
      // Redirect to the chat page where the negotiation happens
      // Wait, we don't have the chat ID from the RPC directly (it returns offer_id).
      // We can redirect to /messages which will show the new chat.
      router.push("/messages")
    } catch (e: any) {
      setError(e.message || "Ошибка при создании запроса")
    } finally {
      setLoading(false)
    }
  }

  if (currentUserId === sellerId) return null;

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button className="w-full font-bold h-12 bg-teal-600 hover:bg-teal-700 text-white rounded-xl shadow-lg">
          <Handshake className="w-5 h-5 mr-2" /> Оптовый запрос
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Запрос на оптовую закупку</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          {error && <div className="text-sm text-destructive font-medium p-3 bg-destructive/10 rounded-lg">{error}</div>}

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="quantity">Количество (шт)</Label>
              <Input 
                id="quantity" 
                type="number" 
                min={minOrderQuantity}
                value={quantity}
                onChange={e => setQuantity(parseInt(e.target.value) || 0)}
                required 
              />
              <p className="text-xs text-muted-foreground">Мин. партия: {minOrderQuantity}</p>
            </div>
            <div className="space-y-2">
              <Label htmlFor="price">Желаемая цена (som)</Label>
              <Input 
                id="price" 
                type="number" 
                min={0}
                value={price}
                onChange={e => setPrice(parseFloat(e.target.value) || 0)}
                required 
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="message">Комментарий для продавца</Label>
            <Textarea 
              id="message" 
              placeholder="Здравствуйте, хочу закупить партию..." 
              value={message}
              onChange={e => setMessage(e.target.value)}
              className="min-h-[100px]"
            />
          </div>

          <Button type="submit" className="w-full h-12 text-lg" disabled={loading || quantity < minOrderQuantity}>
            {loading ? "Отправка..." : "Отправить запрос"}
          </Button>
        </form>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Check, X, Edit2 } from "lucide-react"
import { createClient } from "@/lib/supabase/client"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"

export function B2BOfferCard({ offer, currentUserId }: { offer: any, currentUserId: string }) {
  const isBuyer = currentUserId === offer.buyer_id
  const isSeller = currentUserId === offer.seller_id
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [showCounter, setShowCounter] = useState(false)
  const [counterQty, setCounterQty] = useState(offer.requested_quantity)
  const [counterPrice, setCounterPrice] = useState(offer.requested_price)
  const [counterMessage, setCounterMessage] = useState("")

  const handleAction = async (status: 'ACCEPTED' | 'REJECTED' | 'COUNTER_OFFER') => {
    setLoading(true)
    setError(null)
    try {
      const supabase = createClient()
      const { error: rpcError } = await supabase.rpc("respond_b2b_offer", {
        p_offer_id: offer.id,
        p_status: status,
        p_quantity: status === 'COUNTER_OFFER' ? counterQty : null,
        p_price: status === 'COUNTER_OFFER' ? counterPrice : null,
        p_message: status === 'COUNTER_OFFER' ? counterMessage : null
      })
      if (rpcError) throw rpcError;
      // Ideally we would trigger a refresh here, but realtime or next refresh will pick it up
      window.location.reload()
    } catch (e: any) {
      setError(e.message || "Ошибка")
    } finally {
      setLoading(false)
    }
  }

  const isPending = offer.status === 'PENDING'
  const isCounter = offer.status === 'COUNTER_OFFER'
  const isAccepted = offer.status === 'ACCEPTED'
  const isRejected = offer.status === 'REJECTED'

  return (
    <div className="w-full max-w-sm bg-card border rounded-2xl shadow-sm overflow-hidden my-2 text-[15px]">
      <div className={`px-4 py-2 text-white font-medium text-sm flex justify-between items-center ${isAccepted ? 'bg-green-600' : isRejected ? 'bg-red-600' : 'bg-teal-600'}`}>
        <span>B2B Запрос</span>
        <span className="text-xs uppercase bg-black/20 px-2 py-0.5 rounded-full">{offer.status}</span>
      </div>

      <div className="p-4 space-y-3">
        {error && <div className="text-xs text-destructive">{error}</div>}

        <div className="grid grid-cols-2 gap-2 text-sm border-b pb-3">
          <div>
            <div className="text-muted-foreground text-xs">Запрошено кол-во:</div>
            <div className="font-semibold">{offer.requested_quantity} шт.</div>
          </div>
          <div>
            <div className="text-muted-foreground text-xs">Желаемая цена:</div>
            <div className="font-semibold">{offer.requested_price} som</div>
          </div>
          {offer.buyer_message && (
            <div className="col-span-2 mt-1">
              <div className="text-muted-foreground text-xs">Комментарий покупателя:</div>
              <div className="italic text-muted-foreground">{offer.buyer_message}</div>
            </div>
          )}
        </div>

        {isCounter && (
          <div className="grid grid-cols-2 gap-2 text-sm bg-muted/50 p-2 rounded-xl">
            <div className="col-span-2 font-medium text-teal-700">Встречное предложение продавца:</div>
            <div>
              <div className="text-muted-foreground text-xs">Кол-во:</div>
              <div className="font-semibold">{offer.offered_quantity} шт.</div>
            </div>
            <div>
              <div className="text-muted-foreground text-xs">Цена:</div>
              <div className="font-semibold">{offer.offered_price} som</div>
            </div>
            {offer.seller_message && (
              <div className="col-span-2 mt-1">
                <div className="text-muted-foreground text-xs">Комментарий продавца:</div>
                <div className="italic text-muted-foreground">{offer.seller_message}</div>
              </div>
            )}
          </div>
        )}

        {/* Seller Actions on PENDING */}
        {isSeller && isPending && !showCounter && (
          <div className="flex flex-col gap-2 pt-2">
            <Button size="sm" onClick={() => handleAction('ACCEPTED')} disabled={loading} className="w-full bg-green-600 hover:bg-green-700 text-white">Принять условия</Button>
            <div className="flex gap-2">
              <Button size="sm" variant="outline" onClick={() => setShowCounter(true)} disabled={loading} className="flex-1">Встречное</Button>
              <Button size="sm" variant="outline" onClick={() => handleAction('REJECTED')} disabled={loading} className="flex-1 text-destructive hover:bg-destructive/10">Отклонить</Button>
            </div>
          </div>
        )}

        {/* Seller Counter Form */}
        {isSeller && showCounter && (
          <div className="pt-2 space-y-3 border-t">
            <div className="text-sm font-semibold">Ваше встречное предложение:</div>
            <div className="grid grid-cols-2 gap-2">
              <Input type="number" placeholder="Кол-во" value={counterQty} onChange={e => setCounterQty(Number(e.target.value))} />
              <Input type="number" placeholder="Цена" value={counterPrice} onChange={e => setCounterPrice(Number(e.target.value))} />
            </div>
            <Textarea placeholder="Комментарий (опционально)" value={counterMessage} onChange={e => setCounterMessage(e.target.value)} rows={2} />
            <div className="flex gap-2">
              <Button size="sm" onClick={() => handleAction('COUNTER_OFFER')} disabled={loading} className="flex-1">Отправить</Button>
              <Button size="sm" variant="ghost" onClick={() => setShowCounter(false)}>Отмена</Button>
            </div>
          </div>
        )}

        {/* Buyer Actions on COUNTER_OFFER */}
        {isBuyer && isCounter && (
          <div className="flex gap-2 pt-2">
            <Button size="sm" onClick={() => handleAction('ACCEPTED')} disabled={loading} className="flex-1 bg-green-600 hover:bg-green-700 text-white">Согласиться</Button>
            <Button size="sm" variant="outline" onClick={() => handleAction('REJECTED')} disabled={loading} className="flex-1 text-destructive hover:bg-destructive/10">Отклонить</Button>
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { blockUserAction, unblockUserAction } from "../actions"
import { ShieldAlert, ShieldCheck } from "lucide-react"
import { useRouter } from "next/navigation"
import { useTranslations } from "next-intl";

interface BlockButtonProps {
  userId: string;
  isInitiallyBlocked: boolean;
  variant?: "outline" | "ghost" | "default" | "destructive";
  size?: "default" | "sm" | "lg" | "icon";
}

export function BlockButton({ userId, isInitiallyBlocked, variant = "outline", size = "sm" }: BlockButtonProps) {
    const t = useTranslations();
  const [isBlocked, setIsBlocked] = useState(isInitiallyBlocked)
  const [loading, setLoading] = useState(false)
  const router = useRouter()

  const handleToggleBlock = async () => {
    if (!confirm(isBlocked ? "Разблокировать пользователя?" : "Заблокировать пользователя? Вы не сможете обмениваться сообщениями.")) return;
    
    setLoading(true)
    try {
      if (isBlocked) {
        await unblockUserAction(userId)
        setIsBlocked(false)
      } else {
        await blockUserAction(userId)
        setIsBlocked(true)
      }
      router.refresh()
    } catch (err: any) {
      alert(err.message || "Ошибка")
    } finally {
      setLoading(false)
    }
  }

  return (
    <Button 
      variant={isBlocked ? "secondary" : variant} 
      size={size} 
      onClick={handleToggleBlock} 
      disabled={loading}
      className={isBlocked ? "text-green-600" : "text-destructive hover:text-destructive"}
    >
      {isBlocked ? (
        <><ShieldCheck className="w-4 h-4 mr-2" /> {t("razblokirovat")}</>
      ) : (
        <><ShieldAlert className="w-4 h-4 mr-2" /> {t("zablokirovat")}</>
      )}
    </Button>
  );
}

"use client"

import { useSearchParams, useRouter, usePathname } from "next/navigation"
import { X } from "lucide-react"
import { useTranslations } from "next-intl";

export function CatalogActiveFilters({ categories }: { categories: any[] }) {
    const t = useTranslations();
  const searchParams = useSearchParams()
  const router = useRouter()
  const pathname = usePathname()

  const removeFilter = (key: string) => {
    const current = new URLSearchParams(Array.from(searchParams.entries()))
    current.delete(key)
    current.delete("page")
    router.push(`${pathname}?${current.toString()}`)
  }

  const clearAll = () => {
    router.push(pathname)
  }

  const chips: { key: string, label: string }[] = []

  if (searchParams.get("q")) {
    chips.push({ key: "q", label: `Поиск: ${searchParams.get("q")}` })
  }
  
  if (searchParams.get("category")) {
    const cat = categories.find(c => c.slug === searchParams.get("category"))
    chips.push({ key: "category", label: cat ? cat.name : "Категория" })
  }

  if (searchParams.get("city") && searchParams.get("city") !== "all") {
    chips.push({ key: "city", label: searchParams.get("city") as string })
  }

  if (searchParams.get("condition") && searchParams.get("condition") !== "all") {
    const conditionMap: Record<string, string> = {
      "NEW": "Новое",
      "USED_LIKE_NEW": "Как новое",
      "USED_GOOD": "Хорошее",
      "USED_FAIR": "Нормальное",
      "FOR_PARTS": "На запчасти"
    }
    chips.push({ key: "condition", label: conditionMap[searchParams.get("condition") as string] || "Состояние" })
  }

  const minP = searchParams.get("minPrice")
  const maxP = searchParams.get("maxPrice")
  if (minP || maxP) {
    if (minP && maxP) chips.push({ key: "price_both", label: `${minP} - ${maxP} сом` })
    else if (minP) chips.push({ key: "minPrice", label: `От ${minP} сом` })
    else if (maxP) chips.push({ key: "maxPrice", label: `До ${maxP} сом` })
  }

  if (chips.length === 0) return null

  return (
    <div className="flex items-center gap-2 overflow-x-auto pb-2 -mx-4 px-4 md:mx-0 md:px-0 no-scrollbar mb-4 mt-2">
      {chips.map(chip => (
        <button
          key={chip.key}
          onClick={() => {
            if (chip.key === "price_both") {
              const current = new URLSearchParams(Array.from(searchParams.entries()))
              current.delete("minPrice")
              current.delete("maxPrice")
              current.delete("page")
              router.push(`${pathname}?${current.toString()}`)
            } else {
              removeFilter(chip.key)
            }
          }}
          className="flex items-center gap-1.5 whitespace-nowrap px-3 py-1.5 bg-muted text-foreground hover:bg-muted/80 rounded-full text-sm font-medium transition-colors shrink-0"
        >
          {chip.label}
          <X className="w-3.5 h-3.5 text-muted-foreground" />
        </button>
      ))}
      {chips.length > 1 && (
        <button
          onClick={clearAll}
          className="whitespace-nowrap px-3 py-1.5 text-muted-foreground hover:text-foreground text-sm font-medium transition-colors shrink-0 underline underline-offset-2"
        >
          {t("sbrosit_vsyo")}</button>
      )}
    </div>
  );
}

"use client"
import { useRouter, useSearchParams, usePathname } from "next/navigation"
import { useTransition, useState, useEffect } from "react"
import { Button } from "@/components/ui/button"
import { X, Filter } from "lucide-react"
import { CITIES_BY_REGION } from "@/lib/regions"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
