"use client"

import { useState } from "react"
import { fetchNextCatalogPage } from "@/app/[locale]/(main)/catalog/actions"
import { ProductCard } from "@/components/shared/product-card"
import { Button } from "@/components/ui/button"
import { useTranslations } from "next-intl"

interface CatalogLoadMoreProps {
  initialPage: number;
  searchParams: any;
  totalCount: number;
  categories: any[];
}

export function CatalogLoadMore({ initialPage, searchParams, totalCount, categories }: CatalogLoadMoreProps) {
  const t = useTranslations()
  const [page, setPage] = useState(initialPage)
  const [listings, setListings] = useState<any[]>([])
  const [loading, setLoading] = useState(false)
  
  const to = page * 20 - 1
  const hasMore = totalCount > to + 1
  
  const handleLoadMore = async () => {
    setLoading(true)
    try {
      const nextListings = await fetchNextCatalogPage(searchParams, categories, page + 1)
      setListings(prev => [...prev, ...nextListings])
      setPage(p => p + 1)
    } catch (error) {
      console.error("Failed to load more:", error)
    } finally {
      setLoading(false)
    }
  }

  if (!hasMore && listings.length === 0) return null
  
  return (
    <>
      {listings.length > 0 && (
         <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4 mt-4">
           {listings.map((l: any) => <ProductCard key={l.id} product={l} />)}
         </div>
      )}

      {hasMore && (
         <div className="mt-8 text-center">
            <Button onClick={handleLoadMore} disabled={loading} variant="outline" className="min-w-[200px]">
              {loading ? t("zagruzka_1") : t("zagruzit_eschyo")}
            </Button>
         </div>
      )}
    </>
  );
}

"use client"
import { useState, useRef, useEffect } from "react"
import { Search, ChevronDown, ChevronRight, X } from "lucide-react"
import { useTranslations } from "next-intl";

type Category = { id: string; name: string; slug: string; parent_id?: string | null }

function CategoryNode({ category, categories, value, onChange }: { category: Category, categories: Category[], value: string, onChange: (val: string) => void }) {
  const children = categories.filter(c => c.parent_id === category.id)
  const isActive = value === category.slug

  return (
    <div>
      <button
        className={`w-full text-left px-3 py-2.5 rounded-lg text-sm flex items-center justify-between transition-colors ${
          isActive ? "bg-primary/10 text-primary font-medium" : "hover:bg-muted"
        } ${!category.parent_id ? "font-semibold" : ""}`}
        onClick={() => onChange(category.slug)}
      >
        <span>{category.name}</span>
      </button>
      {children.length > 0 && (
        <div className="pl-4 border-l ml-3 mt-1 space-y-1 border-border/50">
          {children.map(child => (
            <CategoryNode 
              key={child.id} 
              category={child} 
              categories={categories} 
              value={value} 
              onChange={onChange} 
            />
          ))}
        </div>
      )}
    </div>
  )
}

interface CategoryPickerProps {
  categories: Category[]
  value: string
  onChange: (val: string) => void
}

export function CategoryPicker({ categories, value, onChange }: CategoryPickerProps) {
    const t = useTranslations();
  const [isOpen, setIsOpen] = useState(false)
  const [search, setSearch] = useState("")
  const dropdownRef = useRef<HTMLDivElement>(null)

  const selectedCategory = categories.find(c => c.slug === value)

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setIsOpen(false)
      }
    }
    if (isOpen) document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [isOpen])

  // Get children mapping
  const roots = categories.filter(c => !c.parent_id)
  const getChildren = (id: string) => categories.filter(c => c.parent_id === id)

  // Filtered view logic
  const filtered = search 
    ? categories.filter(c => c.name.toLowerCase().includes(search.toLowerCase()))
    : []

  const renderList = () => (
    <div className="flex flex-col h-full md:h-auto md:max-h-[300px]">
      <div className="p-3 border-b md:sticky md:top-0 md:bg-background/95 md:backdrop-blur-sm z-10 shrink-0">
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <input 
            type="text" 
            placeholder={t("poisk_kategorii")} 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-2 bg-muted/50 border-none rounded-lg text-sm focus:outline-none focus:ring-1 focus:ring-primary transition-all"
          />
        </div>
      </div>
      <div className="overflow-y-auto flex-1 p-2 space-y-1">
        <button
          className={`w-full text-left px-3 py-2.5 rounded-lg text-sm flex items-center justify-between transition-colors ${
            !value ? "bg-primary/10 text-primary font-medium" : "hover:bg-muted"
          }`}
          onClick={() => { onChange(""); setIsOpen(false) }}
        >
          {t("vse_kategorii")}</button>

        {search ? (
          // Flat list for search results
          filtered.map(c => (
            <button
              key={c.id}
              className={`w-full text-left px-3 py-2.5 rounded-lg text-sm flex items-center justify-between transition-colors ${
                value === c.slug ? "bg-primary/10 text-primary font-medium" : "hover:bg-muted"
              }`}
              onClick={() => { onChange(c.slug); setIsOpen(false) }}
            >
              {c.name}
            </button>
          ))
        ) : (
          // Hierarchical list
          roots.map(root => (
            <CategoryNode 
              key={root.id} 
              category={root} 
              categories={categories} 
              value={value} 
              onChange={(val) => { onChange(val); setIsOpen(false) }} 
            />
          ))
        )}

        {search && filtered.length === 0 && (
          <div className="px-3 py-4 text-center text-sm text-muted-foreground">
            {t("nichego_ne_naydeno")}</div>
        )}
      </div>
    </div>
  )

  return (
    <>
      <div className="relative" ref={dropdownRef}>
        <button
          type="button"
          className="w-full h-10 px-3 py-2 border rounded-md text-sm bg-background flex items-center justify-between hover:border-primary/50 transition-colors focus:outline-none focus:ring-2 focus:ring-primary/20"
          onClick={() => setIsOpen(!isOpen)}
        >
          <span className="truncate">{selectedCategory ? selectedCategory.name : "Все категории"}</span>
          <ChevronDown className={`w-4 h-4 text-muted-foreground transition-transform ${isOpen ? "rotate-180" : ""}`} />
        </button>

        {/* Desktop Dropdown */}
        {isOpen && (
          <div className="hidden md:block absolute top-full left-0 right-0 mt-1 bg-background border rounded-xl shadow-lg z-50 overflow-hidden animate-in fade-in zoom-in-95 duration-100">
            {renderList()}
          </div>
        )}
      </div>

      {/* Mobile Fullscreen Panel */}
      {isOpen && (
        <div className="md:hidden fixed inset-0 z-[100] bg-background flex flex-col animate-in slide-in-from-bottom-4 duration-200">
          <div className="flex items-center justify-between p-4 border-b shrink-0">
            <h2 className="font-semibold text-lg">{t("vyberite_kategoriyu")}</h2>
            <button 
              className="p-2 -mr-2 text-muted-foreground hover:bg-muted rounded-full transition-colors"
              onClick={() => setIsOpen(false)}
            >
              <X className="w-5 h-5" />
            </button>
          </div>
          {renderList()}
        </div>
      )}
    </>
  );
}

"use client"

import { useState, useEffect, useRef, useCallback } from "react"
import { Send, AlertCircle, ShoppingBag, Loader2 } from "lucide-react"
import { createClient } from "@/lib/supabase/client"
import { sendMessage } from "@/app/actions/chats"
import { Button } from "@/components/ui/button"
import Link from "next/link"
import { useTranslations } from "next-intl";

interface Message {
  id: string
  chat_id: string
  sender_id: string
  content: string
  is_read: boolean
  created_at: string
}

import { B2BOfferCard } from "@/features/b2b/components/offer-card"

interface ChatRoomProps {
  chatId: string
  currentUserId: string
  initialMessages: Message[]
  b2bOffers?: any[]
  listing?: any
  isBlocked?: boolean
}

export function ChatRoom({ chatId, currentUserId, initialMessages, b2bOffers = [], listing, isBlocked }: ChatRoomProps) {
    const t = useTranslations();
  const [messages, setMessages] = useState<Message[]>(initialMessages)
  const [offers, setOffers] = useState<any[]>(b2bOffers)
  const [content, setContent] = useState("")
  const [isSending, setIsSending] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [isConnected, setIsConnected] = useState(true)
  
  const [isLoadingMore, setIsLoadingMore] = useState(false)
  const [hasMore, setHasMore] = useState(initialMessages.length >= 50)

  const messagesEndRef = useRef<HTMLDivElement>(null)
  const textareaRef = useRef<HTMLTextAreaElement>(null)
  const scrollContainerRef = useRef<HTMLDivElement>(null)
  const supabase = createClient()

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "instant" })
  }

  // Load older messages
  const loadOlderMessages = async () => {
    if (isLoadingMore || !hasMore || messages.length === 0) return
    setIsLoadingMore(true)
    
    const oldestMessage = messages[0]
    
    const { data, error } = await supabase
      .from("messages")
      .select("*")
      .eq("chat_id", chatId)
      .lt("created_at", oldestMessage.created_at)
      .order("created_at", { ascending: false })
      .limit(50)

    if (!error && data) {
      if (data.length < 50) setHasMore(false)
      if (data.length > 0) {
        // Reverse because we queried DESC
        const olderMessages = data.reverse() as Message[]
        
        // Remember scroll position
        const scrollContainer = scrollContainerRef.current
        const previousScrollHeight = scrollContainer?.scrollHeight || 0

        setMessages(prev => {
          // Prevent duplicates
          const newMsgs = olderMessages.filter(newM => !prev.some(m => m.id === newM.id))
          return [...newMsgs, ...prev]
        })

        // Restore scroll position after render
        setTimeout(() => {
          if (scrollContainer) {
            scrollContainer.scrollTop = scrollContainer.scrollHeight - previousScrollHeight
          }
        }, 0)
      }
    }
    setIsLoadingMore(false)
  }

  // Handle read receipts
  useEffect(() => {
    const unreadMessages = messages.filter(m => !m.is_read && m.sender_id !== currentUserId)
    if (unreadMessages.length > 0) {
      const unreadIds = unreadMessages.map(m => m.id)
      
      // Update DB
      supabase.from('messages')
        .update({ is_read: true })
        .in('id', unreadIds)
        .then((res: { error: any }) => {
          if (!res.error) {
            // Update local state only if DB update succeeded
            setMessages(prev => prev.map(m => 
              unreadIds.includes(m.id) ? { ...m, is_read: true } : m
            ))
          }
        })
    }
  }, [messages, currentUserId, supabase])

  // Realtime subscription and Reconciliation
  useEffect(() => {
    // Initial scroll
    scrollToBottom()

    let channel = supabase.channel(`chat_${chatId}`)

    channel
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'messages', filter: `chat_id=eq.${chatId}` },
        (payload: any) => {
          const newMessage = payload.new as Message
          setMessages(prev => {
            if (prev.some(m => m.id === newMessage.id)) return prev
            // if we are at bottom, scroll down after state update
            setTimeout(() => {
               scrollToBottom()
            }, 50)
            return [...prev, newMessage]
          })
        }
      )
      .subscribe(async (status: any) => {
        setIsConnected(status === 'SUBSCRIBED')
        
        if (status === 'SUBSCRIBED') {
          // Reconciliation: Fetch any messages we might have missed during disconnect
          setMessages(currentMessages => {
            if (currentMessages.length === 0) return currentMessages;
            const lastMsg = currentMessages[currentMessages.length - 1]
            
            // Fetch newer messages async
            supabase
              .from('messages')
              .select('*')
              .eq('chat_id', chatId)
              .gt('created_at', lastMsg.created_at)
              .order('created_at', { ascending: true })
              .then((res: { data: any, error: any }) => {
                if (!res.error && res.data && res.data.length > 0) {
                  setMessages(prev => {
                    const newMsgs = res.data.filter((newM: any) => !prev.some(m => m.id === newM.id))
                    if (newMsgs.length > 0) {
                      setTimeout(scrollToBottom, 50)
                      return [...prev, ...newMsgs]
                    }
                    return prev
                  })
                }
              })
            return currentMessages;
          })
        }
      })
      
    return () => { 
      supabase.removeChannel(channel) 
    }
  }, [chatId, supabase])

  const handleSend = async () => {
    const trimmed = content.trim()
    if (!trimmed || isSending) return

    setIsSending(true)
    setError(null)
    
    // reset height
    if (textareaRef.current) {
      textareaRef.current.style.height = '44px'
    }

    const result = await sendMessage(chatId, trimmed)
    if (!result.success) {
      setError(result.error || "Ошибка отправки")
    } else if (result.message) {
      setContent("")
      setMessages(prev => {
        if (prev.some(m => m.id === result.message.id)) return prev
        setTimeout(scrollToBottom, 50)
        return [...prev, result.message as Message]
      })
    }
    setIsSending(false)
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }

  const handleInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setContent(e.target.value)
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto'
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 120) + 'px'
    }
  }

  // Group timeline
  const timeline = [
    ...messages.map(m => ({ ...m, _type: 'message' })),
    ...offers.map(o => ({ ...o, _type: 'offer' }))
  ].sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())

  const grouped: { date: string, items: any[] }[] = []
  
  timeline.forEach((item, idx) => {
    const d = new Date(item.created_at)
    const dateStr = d.toLocaleDateString("ru-RU", { day: 'numeric', month: 'long' })
    
    let currentGroup = grouped.find(g => g.date === dateStr)
    if (!currentGroup) {
      currentGroup = { date: dateStr, items: [] }
      grouped.push(currentGroup)
    }
    
    if (item._type === 'offer') {
      currentGroup.items.push(item)
    } else {
      const prevItem = idx > 0 ? timeline[idx - 1] : null
      const nextItem = idx < timeline.length - 1 ? timeline[idx + 1] : null
      
      const isSameSenderAsPrev = prevItem && prevItem._type === 'message' && prevItem.sender_id === item.sender_id
      const isSameSenderAsNext = nextItem && nextItem._type === 'message' && nextItem.sender_id === item.sender_id
      
      const isSameTimeAsPrev = prevItem && (d.getTime() - new Date(prevItem.created_at).getTime() < 60000)
      const isSameTimeAsNext = nextItem && (new Date(nextItem.created_at).getTime() - d.getTime() < 60000)

      const isFirstInGroup = !(isSameSenderAsPrev && isSameTimeAsPrev)
      const isLastInGroup = !(isSameSenderAsNext && isSameTimeAsNext)

      currentGroup.items.push({ ...item, isFirstInGroup, isLastInGroup })
    }
  })

  return (
    <div className="flex flex-col flex-1 bg-background relative overflow-hidden">
      {!isConnected && (
        <div className="bg-destructive/10 text-destructive px-3 py-1.5 text-[11px] font-medium flex items-center justify-center gap-1.5 shrink-0">
          <AlertCircle className="w-3 h-3" />
          <span>{t("perepodklyuchenie")}</span>
        </div>
      )}

      <div ref={scrollContainerRef} className="flex-1 overflow-y-auto px-2 sm:px-4 py-4 space-y-6 flex flex-col">
        {hasMore && (
          <div className="flex justify-center shrink-0 mb-4">
            <Button 
              variant="outline" 
              size="sm" 
              onClick={loadOlderMessages} 
              disabled={isLoadingMore}
              className="text-xs rounded-full h-8 px-4 bg-muted/30"
            >
              {isLoadingMore ? <Loader2 className="w-3 h-3 animate-spin mr-2" /> : null}
              {isLoadingMore ? "Загрузка..." : "Загрузить старые"}
            </Button>
          </div>
        )}

        {listing && (
          <div className="flex justify-center shrink-0">
            <Link href={`/product/${listing.id}`} className="bg-muted/30 hover:bg-muted/50 transition-colors border border-border/50 rounded-2xl p-2 flex items-center gap-3 w-full max-w-[320px] shadow-sm group outline-none">
              <div className="w-12 h-12 rounded-xl bg-muted overflow-hidden shrink-0 relative">
                {listing.listing_images?.[0]?.url ? (
                  <img src={listing.listing_images[0].url} className="w-full h-full object-cover" alt="Product" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-muted-foreground"><ShoppingBag className="w-5 h-5" /></div>
                )}
                {listing.status && listing.status !== 'ACTIVE' && (
                  <div className="absolute inset-0 bg-background/80 flex items-center justify-center text-center px-1">
                    <span className="text-[9px] font-bold uppercase">
                      {listing.status === 'SOLD' ? 'Продано' : 
                       listing.status === 'ARCHIVED' ? 'В архиве' : 
                       listing.status === 'OUT_OF_STOCK' ? 'Нет в наличии' : 
                       listing.status === 'BLOCKED' ? 'Заблокировано' : 
                       'Неактивно'}
                    </span>
                  </div>
                )}
              </div>
              <div className="flex-1 min-w-0 pr-1">
                <p className="text-[13px] font-semibold leading-tight truncate text-foreground group-hover:text-primary transition-colors">{listing.title}</p>
                <p className="text-[12px] font-bold text-muted-foreground mt-0.5">{listing.price?.toLocaleString("ru-RU")} {t("som")}</p>
              </div>
            </Link>
          </div>
        )}

        {messages.length === 0 && offers.length === 0 ? (
          <div className="flex flex-col items-center justify-center text-muted-foreground text-sm flex-1 opacity-60">
            <p>{t("dialog_nachat")}</p>
          </div>
        ) : (
          grouped.map((group) => (
            <div key={group.date} className="space-y-1.5 flex flex-col">
              <div className="flex justify-center my-3">
                <span className="bg-muted/40 text-muted-foreground px-3 py-1 rounded-full text-[11px] font-medium shadow-sm">
                  {group.date}
                </span>
              </div>
              
              {group.items.map((item) => {
                if (item._type === 'offer') {
                  return (
                    <div key={`offer-${item.id}`} className="flex justify-center w-full my-4">
                      <B2BOfferCard offer={item} currentUserId={currentUserId} />
                    </div>
                  )
                }

                const msg = item
                const isMe = msg.sender_id === currentUserId
                const time = new Date(msg.created_at).toLocaleTimeString("ru-RU", { hour: '2-digit', minute: '2-digit' })
                
                // Smart border radius
                const roundedTL = !isMe && !msg.isFirstInGroup ? 'rounded-tl-sm' : 'rounded-tl-2xl'
                const roundedTR = isMe && !msg.isFirstInGroup ? 'rounded-tr-sm' : 'rounded-tr-2xl'
                const roundedBL = !isMe && !msg.isLastInGroup ? 'rounded-bl-sm' : 'rounded-bl-2xl'
                const roundedBR = isMe && !msg.isLastInGroup ? 'rounded-br-sm' : 'rounded-br-2xl'

                return (
                  <div key={msg.id} className={`flex flex-col w-full ${isMe ? 'items-end' : 'items-start'}`}>
                    <div 
                      className={`relative max-w-[85%] sm:max-w-[75%] px-3.5 py-2 text-[15px] leading-[1.35] whitespace-pre-wrap break-words shadow-sm transition-all ${
                        isMe 
                          ? `bg-[#0a8657] text-white ${roundedTL} ${roundedTR} ${roundedBL} ${roundedBR}` 
                          : `bg-muted/70 text-foreground border border-border/30 ${roundedTL} ${roundedTR} ${roundedBL} ${roundedBR}`
                      } ${!msg.isLastInGroup ? 'mb-[2px]' : 'mb-0'}`}
                    >
                      {msg.content}
                      {msg.isLastInGroup && (
                        <div className={`flex items-center justify-end gap-1 mt-1 -mb-1 -mr-1 ${isMe ? 'text-white/70' : 'text-muted-foreground/70'}`}>
                          <span className="text-[9px] leading-none">{time}</span>
                        </div>
                      )}
                    </div>
                  </div>
                )
              })}
            </div>
          ))
        )}
        <div ref={messagesEndRef} className="h-1 shrink-0" />
      </div>

      <div className="p-2 sm:p-3 bg-background border-t shrink-0 relative z-10 shadow-[0_-10px_20px_rgba(0,0,0,0.02)]">
        {error && <p className="text-destructive text-xs mb-2 px-2 text-center font-medium">{error}</p>}
        {isBlocked ? (
          <div className="flex items-center justify-center p-3 text-muted-foreground text-sm font-medium bg-muted/50 rounded-xl">
            {t("otpravka_soobscheniy_ogranichena_tak")}</div>
        ) : (
          <div className="flex items-end gap-2 max-w-4xl mx-auto">
            <div className="flex-1 bg-muted/40 rounded-[22px] border border-border/60 focus-within:border-primary focus-within:bg-background transition-colors flex items-end shadow-sm overflow-hidden">
              <textarea
                ref={textareaRef}
                value={content}
                onChange={handleInput}
                onKeyDown={handleKeyDown}
                placeholder={t("napisat_soobschenie")}
                className="flex-1 max-h-[120px] min-h-[44px] py-[11px] px-4 bg-transparent outline-none resize-none text-[15px] leading-relaxed no-scrollbar"
                rows={1}
                disabled={isSending}
              />
            </div>
            <Button 
              onClick={handleSend} 
              disabled={isSending || !content.trim()} 
              className="h-[44px] w-[44px] shrink-0 rounded-full p-0 flex items-center justify-center shadow-md transition-transform active:scale-95 bg-primary text-primary-foreground hover:bg-primary/90"
              size="icon"
            >
              <Send className="w-5 h-5 -ml-0.5" />
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

"use client"

import { useState } from "react"
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs"
import { Button } from "@/components/ui/button"
import { updateListingStatus } from "@/app/actions/listings"
import { MoreVertical, Archive, Power, PowerOff, Edit2, CheckCircle2, Plus } from "lucide-react"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger, DropdownMenuSeparator } from "@/components/ui/dropdown-menu"
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog"
import Link from "next/link"

import { useRouter } from "next/navigation"
import { useTranslations } from "next-intl";

export function MyListingsClient({ listings, status = "all", page = 1, totalPages = 1, totalCount = 0 }: { listings: any[], status?: string, page?: number, totalPages?: number, totalCount?: number }) {
    const t = useTranslations();
  const [isDeleting, setIsDeleting] = useState<string | null>(null)
  const [isUpdating, setIsUpdating] = useState<string | null>(null)
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null)
  const router = useRouter()

  const handleStatusChange = async (id: string, status: string) => {
    setIsUpdating(id)
    await updateListingStatus(id, status)
    setIsUpdating(null)
  }

  const handleDelete = async () => {
    if (!deleteConfirmId) return
    setIsDeleting(deleteConfirmId)
    await updateListingStatus(deleteConfirmId, "ARCHIVED")
    setIsDeleting(null)
    setDeleteConfirmId(null)
  }

  const ListingCard = ({ listing }: { listing: any }) => {
    const images = listing.listing_images?.sort((a: any, b: any) => a.order_index - b.order_index) || []
    const mainImage = images.length > 0 ? images[0].url : "/placeholder.png"

    return (
      <div className={`flex gap-3 sm:gap-4 p-3 sm:p-4 border rounded-2xl bg-card transition-opacity ${isUpdating === listing.id ? 'opacity-50 pointer-events-none' : ''}`}>
        {/* Mobile: 96x96 image, Desktop: 128x128 */}
        <div className="w-24 h-24 sm:w-32 sm:h-32 shrink-0 rounded-xl overflow-hidden bg-muted">
          <img src={mainImage} className="w-full h-full object-cover" alt="" />
        </div>

        <div className="flex-1 flex flex-col justify-between min-w-0">
          <div>
            <div className="flex items-start justify-between gap-2">
              <h3 className="font-semibold text-sm sm:text-lg line-clamp-2">{listing.title}</h3>
              {/* Action Menu for Mobile (and Desktop if preferred, but let's keep it clean) */}
              {listing.status !== "ARCHIVED" && listing.status !== "SOLD" && (
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant="ghost" size="icon" className="h-8 w-8 -mt-1 -mr-2 shrink-0">
                      <MoreVertical className="w-4 h-4" />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-48">
                    <DropdownMenuItem asChild>
                      <Link href={`/sell?edit=${listing.id}`}>
                        <Edit2 className="w-4 h-4 mr-2" /> {t("redaktirovat")}</Link>
                    </DropdownMenuItem>
                    {listing.status === "ACTIVE" || listing.status === "OUT_OF_STOCK" ? (
                      <DropdownMenuItem onClick={() => handleStatusChange(listing.id, "DEACTIVATED")}>
                        <PowerOff className="w-4 h-4 mr-2" /> {t("deaktivirovat")}</DropdownMenuItem>
                    ) : (
                      <DropdownMenuItem onClick={() => handleStatusChange(listing.id, "ACTIVE")}>
                        <Power className="w-4 h-4 mr-2" /> {t("aktivirovat")}</DropdownMenuItem>
                    )}
                    <DropdownMenuItem onClick={() => handleStatusChange(listing.id, "SOLD")}>
                      <CheckCircle2 className="w-4 h-4 mr-2" /> {t("otmetit_prodannym")}</DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem className="text-destructive focus:text-destructive" onClick={() => setDeleteConfirmId(listing.id)}>
                      <Archive className="w-4 h-4 mr-2" /> {t("udalit")}</DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              )}
            </div>
            <p className="font-bold whitespace-nowrap text-sm sm:text-lg text-primary">{listing.price.toLocaleString("ru-RU")} {t("som")}</p>
            <p className="text-xs sm:text-sm text-muted-foreground mt-1 truncate">
              {new Date(listing.created_at).toLocaleDateString()} • {listing.city}
            </p>
            {listing.listing_type === "INVENTORY" && (
              <p className="text-xs text-muted-foreground mt-0.5">{t("v_nalichii")}{listing.quantity} {t("sht_1")}</p>
            )}
          </div>

          <div className="flex items-center mt-3">
            {listing.status === "SOLD" && (
              <span className="flex items-center gap-1.5 text-xs sm:text-sm font-medium text-green-600 bg-green-500/10 px-2 py-1 sm:px-2.5 rounded-full">
                <CheckCircle2 className="w-3 h-3 sm:w-4 sm:h-4" /> {t("prodano")}</span>
            )}
            {listing.status === "ARCHIVED" && (
              <span className="flex items-center gap-1.5 text-xs sm:text-sm font-medium text-muted-foreground bg-muted px-2 py-1 sm:px-2.5 rounded-full">
                <Archive className="w-3 h-3 sm:w-4 sm:h-4" /> {t("v_arhive")}</span>
            )}
            {listing.status === "OUT_OF_STOCK" && (
              <span className="flex items-center gap-1.5 text-xs sm:text-sm font-medium text-orange-600 bg-orange-500/10 px-2 py-1 sm:px-2.5 rounded-full">
                {t("net_v_nalichii")}</span>
            )}
            {listing.status === "ACTIVE" && (
              <span className="flex items-center gap-1.5 text-xs sm:text-sm font-medium text-primary bg-primary/10 px-2 py-1 sm:px-2.5 rounded-full">
                {t("aktivno")}</span>
            )}
            {listing.status === "DEACTIVATED" && (
              <span className="flex items-center gap-1.5 text-xs sm:text-sm font-medium text-muted-foreground bg-muted px-2 py-1 sm:px-2.5 rounded-full">
                {t("deaktivirovano")}</span>
            )}
          </div>
        </div>
      </div>
    );
  }

  const EmptyState = ({ title, showCTA = true }: { title: string, showCTA?: boolean }) => (
    <div className="flex flex-col items-center justify-center text-center py-16 border rounded-2xl bg-muted/20 px-4">
      <p className="text-muted-foreground font-medium mb-4">{title}</p>
      {showCTA && (
        <Button asChild>
          <Link href="/sell">
            <Plus className="w-4 h-4 mr-2" />
            {t("razmestit_tovar")}</Link>
        </Button>
      )}
    </div>
  )

  const handleTabChange = (val: string) => {
    router.push(`/my-listings?status=${val}`)
  }

  const buildPageUrl = (p: number) => {
    return `/my-listings?status=${status}&page=${p}`
  }

  return (
    <>
      <Tabs value={status} onValueChange={handleTabChange} className="w-full">
        {/* Mobile-friendly tabs wrapper */}
        <div className="-mx-4 px-4 sm:mx-0 sm:px-0 overflow-x-auto no-scrollbar mb-6">
          <TabsList className="inline-flex w-max min-w-full justify-start rounded-none border-b bg-transparent h-auto p-0 gap-6">
            <TabsTrigger value="all" className="data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:border-b-2 data-[state=active]:border-primary rounded-none px-0 pb-3 text-sm sm:text-base">
              {t("vse")}{status === "all" && <span className="ml-2 text-xs bg-muted px-2 py-0.5 rounded-full">{totalCount}</span>}
            </TabsTrigger>
            <TabsTrigger value="active" className="data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:border-b-2 data-[state=active]:border-primary rounded-none px-0 pb-3 text-sm sm:text-base">
              {t("aktivnye")}{status === "active" && <span className="ml-2 text-xs bg-muted px-2 py-0.5 rounded-full">{totalCount}</span>}
            </TabsTrigger>
            <TabsTrigger value="sold" className="data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:border-b-2 data-[state=active]:border-primary rounded-none px-0 pb-3 text-sm sm:text-base">
              {t("prodannye")}{status === "sold" && <span className="ml-2 text-xs bg-muted px-2 py-0.5 rounded-full">{totalCount}</span>}
            </TabsTrigger>
            <TabsTrigger value="deactivated" className="data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:border-b-2 data-[state=active]:border-primary rounded-none px-0 pb-3 text-sm sm:text-base">
              {t("deaktivirovannye")}{status === "deactivated" && <span className="ml-2 text-xs bg-muted px-2 py-0.5 rounded-full">{totalCount}</span>}
            </TabsTrigger>
            <TabsTrigger value="archived" className="data-[state=active]:bg-transparent data-[state=active]:shadow-none data-[state=active]:border-b-2 data-[state=active]:border-primary rounded-none px-0 pb-3 text-sm sm:text-base">
              {t("arhiv")}{status === "archived" && <span className="ml-2 text-xs bg-muted px-2 py-0.5 rounded-full">{totalCount}</span>}
            </TabsTrigger>
          </TabsList>
        </div>

        <div className="space-y-4 outline-none">
          {listings.length === 0 ? <EmptyState title={t("net_obyavleniy")} /> : listings.map(l => <ListingCard key={l.id} listing={l} />)}
        </div>
        
        {totalPages > 1 && (
          <div className="mt-8 flex justify-center gap-2">
            <Button variant="outline" disabled={page <= 1} asChild={page > 1}>
              {page > 1 ? <Link href={buildPageUrl(page - 1)}>{t("nazad")}</Link> : <span>{t("nazad")}</span>}
            </Button>
            <Button variant="outline" disabled={page >= totalPages} asChild={page < totalPages}>
              {page < totalPages ? <Link href={buildPageUrl(page + 1)}>{t("vpered")}</Link> : <span>{t("vpered")}</span>}
            </Button>
          </div>
        )}
      </Tabs>

      <AlertDialog open={!!deleteConfirmId} onOpenChange={(open) => !open && setDeleteConfirmId(null)}>
        <AlertDialogContent className="w-[90vw] max-w-md rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle>{t("udalit_obyavlenie")}</AlertDialogTitle>
            <AlertDialogDescription>
              {t("ono_perestanet_otobrazhatsya_pokupatelyam")}</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter className="flex-col sm:flex-row gap-2 mt-2">
            <AlertDialogCancel className="mt-0 w-full sm:w-auto">{t("otmena")}</AlertDialogCancel>
            <AlertDialogAction 
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90 w-full sm:w-auto" 
              onClick={(e) => { e.preventDefault(); handleDelete(); }}
              disabled={!!isDeleting}
            >
              {isDeleting ? "Удаление..." : "Удалить"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

"use client"

import * as React from "react"
import { useEffect, useState } from "react"
import { Bell, Check, Trash } from "lucide-react"
import { useRouter } from "next/navigation"

import { Button } from "@/components/ui/button"
import { createClient } from "@/lib/supabase/client"
import { useTranslations } from "next-intl";

export function NotificationsDropdown() {
    const t = useTranslations();
  const [notifications, setNotifications] = useState<any[]>([])
  const [unreadCount, setUnreadCount] = useState(0)
  const [isOpen, setIsOpen] = useState(false)
  
  const router = useRouter()
  const supabase = createClient()

  const fetchNotifications = async () => {
    const { data: { session } } = await supabase.auth.getSession()
    if (!session) return

    const { data } = await supabase
      .from("notifications")
      .select("*")
      .eq("user_id", session.user.id)
      .order("created_at", { ascending: false })
      .limit(50)

    if (data) {
      setNotifications(data)
      const { data: countData } = await supabase.rpc("get_unread_notifications_count")
      setUnreadCount(countData || 0)
    }
  }

  useEffect(() => {
    fetchNotifications()

    // Realtime subscription specifically for this user's notifications
    let isMounted = true
    let subscription: any = null

    supabase.auth.getSession().then(({ data: { session } }: any) => {
      if (!isMounted || !session) return

      // Append random string to channel name to prevent "already subscribed" errors 
      // during React StrictMode or HMR rapid mount/unmount cycles.
      const channelName = `notifications_${session.user.id}_${Math.random().toString(36).substring(7)}`

      subscription = supabase
        .channel(channelName)
        .on(
          "postgres_changes",
          {
            event: "*",
            schema: "public",
            table: "notifications",
            filter: `user_id=eq.${session.user.id}`,
          },
          () => {
            fetchNotifications()
          }
        )
        .subscribe()
    })

    return () => {
      isMounted = false
      if (subscription) {
        supabase.removeChannel(subscription)
      }
    }
  }, [])

  const markAsRead = async (id: string) => {
    await supabase.from("notifications").update({ is_read: true }).eq("id", id)
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, is_read: true } : n))
    setUnreadCount(prev => Math.max(0, prev - 1))
  }

  const markAllAsRead = async () => {
    const { data: { session } } = await supabase.auth.getSession()
    if (!session) return

    await supabase
      .from("notifications")
      .update({ is_read: true })
      .eq("user_id", session.user.id)
      .eq("is_read", false)
      
    setNotifications(prev => prev.map(n => ({ ...n, is_read: true })))
    setUnreadCount(0)
  }

  const handleNotificationClick = (notification: any) => {
    if (!notification.is_read) {
      markAsRead(notification.id)
    }
    setIsOpen(false)
    if (notification.link) {
      router.push(notification.link)
    }
  }

  return (
    <div className="relative">
      <Button
        variant="ghost"
        size="icon"
        className="relative h-9 w-9 text-muted-foreground hover:text-foreground"
        onClick={() => setIsOpen(!isOpen)}
        aria-label={t("uvedomleniya")}
      >
        <Bell className="w-5 h-5" />
        {unreadCount > 0 && (
          <span className="absolute -top-1 -right-1 w-5 h-5 flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full border-2 border-background">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </Button>

      {isOpen && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setIsOpen(false)} />
          <div className="absolute right-0 top-full mt-2 w-80 bg-popover rounded-xl shadow-lg border p-1 z-50 overflow-hidden flex flex-col max-h-[80vh]">
            <div className="px-3 py-3 border-b flex items-center justify-between">
              <h3 className="font-semibold">{t("uvedomleniya")}</h3>
              {unreadCount > 0 && (
                <button
                  onClick={markAllAsRead}
                  className="text-xs text-primary hover:underline flex items-center gap-1"
                >
                  <Check className="w-3 h-3" /> {t("prochitat_vse")}</button>
              )}
            </div>

            <div className="overflow-y-auto flex-1 p-1">
              {notifications.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground text-sm">
                  {t("net_novyh_uvedomleniy")}</div>
              ) : (
                <div className="space-y-1">
                  {notifications.map(notification => (
                    <div
                      key={notification.id}
                      onClick={() => handleNotificationClick(notification)}
                      className={`p-3 rounded-lg cursor-pointer transition-colors text-sm ${
                        notification.is_read
                          ? "hover:bg-muted opacity-70"
                          : "bg-primary/5 hover:bg-primary/10 border border-primary/10"
                      }`}
                    >
                      <div className="flex justify-between gap-2 mb-1">
                        <span className="font-medium text-foreground">
                          {notification.type === "NEW_MESSAGE" ? "Новое сообщение" :
                           notification.type === "NEW_OFFER" ? "Новое предложение" :
                           notification.type === "NEW_ORDER" ? "Новый заказ" :
                           notification.type === "ORDER_STATUS" ? "Статус заказа" : "Уведомление"}
                        </span>
                        <span className="text-[10px] text-muted-foreground whitespace-nowrap">
                          {new Date(notification.created_at).toLocaleDateString()}
                        </span>
                      </div>
                      <p className="text-muted-foreground line-clamp-2 text-xs">
                        {notification.message}
                      </p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </>
      )}
    </div>
  );
}

"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Textarea } from "@/components/ui/textarea"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog"
import { Star } from "lucide-react"
import { submitReviewAction } from "@/features/reviews/actions/submit-review"
import { useTranslations } from "next-intl"

export function LeaveReviewButton({ orderId, existingReview }: { orderId: string, existingReview?: any }) {
  const t = useTranslations()
  const [open, setOpen] = useState(false)
  const [rating, setRating] = useState(5)
  const [comment, setComment] = useState("")
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  if (existingReview) {
    return (
      <div className="mt-6 pt-6 border-t">
        <h4 className="font-semibold mb-2">Ваш отзыв</h4>
        <div className="flex gap-1 mb-2">
          {[1, 2, 3, 4, 5].map((star) => (
            <Star key={star} className={`w-4 h-4 ${star <= existingReview.rating ? "fill-amber-400 text-amber-400" : "text-muted"}`} />
          ))}
        </div>
        <p className="text-sm text-muted-foreground">{existingReview.comment}</p>
        {existingReview.reply && (
          <div className="mt-3 p-3 bg-muted/30 rounded-xl text-sm border-l-2 border-primary">
            <span className="font-semibold block mb-1">Ответ продавца:</span>
            {existingReview.reply}
          </div>
        )}
      </div>
    )
  }

  const handleSubmit = async () => {
    setLoading(true)
    setError(null)
    const res = await submitReviewAction(orderId, rating, comment)
    setLoading(false)
    if (res.error) {
      setError(res.error)
    } else {
      setOpen(false)
    }
  }

  return (
    <div className="mt-6 pt-6 border-t">
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogTrigger asChild>
          <Button variant="outline" className="w-full sm:w-auto">Оставить отзыв</Button>
        </DialogTrigger>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Оцените сделку</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4">
            {error && <div className="text-sm text-destructive font-medium p-3 bg-destructive/10 rounded-lg">{error}</div>}

            <div className="flex justify-center gap-2 mb-6">
              {[1, 2, 3, 4, 5].map((star) => (
                <button 
                  key={star} 
                  type="button"
                  onClick={() => setRating(star)}
                  className="p-1 hover:scale-110 transition-transform"
                >
                  <Star className={`w-8 h-8 ${star <= rating ? "fill-amber-400 text-amber-400" : "text-muted"}`} />
                </button>
              ))}
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">Комментарий</label>
              <Textarea 
                placeholder="Расскажите о впечатлениях..." 
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                className="min-h-[100px]"
              />
            </div>

            <Button 
              className="w-full mt-4" 
              onClick={handleSubmit}
              disabled={loading || rating < 1}
            >
              {loading ? "Отправка..." : "Опубликовать отзыв"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

"use client"

import { useState } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
