  DialogTrigger,
} from "@/components/ui/dialog"
import { createReportAction } from "../actions"
import { Flag } from "lucide-react"
import { useTranslations } from "next-intl";

interface ReportModalProps {
  targetId: string;
  targetType: 'LISTING' | 'USER' | 'MESSAGE' | 'STORE';
  trigger?: React.ReactNode;
}

const REPORT_REASONS = [
  "Запрещенный товар",
  "Мошенничество",
  "Спам",
  "Оскорбительное поведение",
  "Нарушение интеллектуальной собственности",
  "Другое"
]

export function ReportModal({ targetId, targetType, trigger }: ReportModalProps) {
    const t = useTranslations();
  const [open, setOpen] = useState(false)
  const [reason, setReason] = useState(REPORT_REASONS[0])
  const [description, setDescription] = useState("")
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState(false)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setLoading(true)
    setError(null)
    try {
      await createReportAction({ targetId, targetType, reason, description })
      setSuccess(true)
      setTimeout(() => {
        setOpen(false)
        setSuccess(false)
      }, 2000)
    } catch (err: any) {
      setError(err.message || "Ошибка при отправке жалобы")
    } finally {
      setLoading(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        {trigger || (
          <Button variant="outline" size="sm" className="gap-2 text-muted-foreground hover:text-red-500">
            <Flag className="w-4 h-4" /> {t("pozhalovatsya")}</Button>
        )}
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{t("pozhalovatsya")}</DialogTitle>
          <DialogDescription>
            {t("vasha_zhaloba_budet_anonimno")}</DialogDescription>
        </DialogHeader>

        {success ? (
          <div className="py-6 text-center text-green-600 font-medium">
            {t("zhaloba_uspeshno_otpravlena_spasibo")}</div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4 mt-4">
            {error && <div className="text-sm text-red-500 bg-red-50 p-2 rounded-md">{error}</div>}
            
            <div className="space-y-2">
              <label className="text-sm font-medium">{t("prichina")}</label>
              <select 
                className="flex h-10 w-full items-center justify-between rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                value={reason}
                onChange={(e) => setReason(e.target.value)}
              >
                {REPORT_REASONS.map(r => (
                  <option key={r} value={r}>{r}</option>
                ))}
              </select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium">{t("dopolnitelnye_detali_neobyazatelno")}</label>
              <Textarea 
                placeholder={t("opishite_problemu_podrobnee")} 
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                rows={3}
              />
            </div>

            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? "Отправка..." : "Отправить жалобу"}
            </Button>
          </form>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client"
import { useState } from "react"
import { useRouter } from "next/navigation"
import { offerListing } from "@/app/actions/requests"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Loader2 } from "lucide-react"
import Link from "next/link"
import { useTranslations } from "next-intl";

export function OfferForm({ requestId, sellerListings }: { requestId: string, sellerListings: any[] }) {
    const t = useTranslations();
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [listingId, setListingId] = useState("")
  const [message, setMessage] = useState("")

  const onSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!listingId) {
      setError("Выберите товар для предложения")
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      const result = await offerListing(requestId, listingId, message || "Здравствуйте, предлагаю вам этот товар.")
      if (result.error) {
        setError(result.error)
        setIsLoading(false)
      } else {
        router.refresh()
      }
    } catch (err: any) {
      setError(err.message)
      setIsLoading(false)
    }
  }

  if (sellerListings.length === 0) {
    return (
      <div className="text-center py-8">
        <p className="text-muted-foreground mb-4">{t("u_vas_net_aktivnyh")}</p>
        <Button asChild className="rounded-xl">
          <Link href="/sell">{t("razmestit_tovar")}</Link>
        </Button>
      </div>
    );
  }

  return (
    <form onSubmit={onSubmit} className="space-y-4 max-w-md">
      {error && (
        <div className="p-4 bg-destructive/10 text-destructive border border-destructive/20 rounded-xl text-sm font-medium">
          {error}
        </div>
      )}

      <div className="space-y-2">
        <Label>{t("vyberite_tovar")}</Label>
        <Select value={listingId} onValueChange={setListingId}>
          <SelectTrigger className="h-12 bg-background border-primary/20">
            <SelectValue placeholder={t("vashi_aktivnye_obyavleniya")} />
          </SelectTrigger>
          <SelectContent>
            {sellerListings.map(l => (
              <SelectItem key={l.id} value={l.id}>
                {l.title} — {l.price.toLocaleString("ru-RU")} {t("som")}</SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="space-y-2">
        <Label>{t("soobschenie_optsionalno")}</Label>
        <Textarea 
          value={message} 
          onChange={(e) => setMessage(e.target.value)} 
          className="bg-background border-primary/20 min-h-[80px]" 
          placeholder={t("napishite_korotkoe_soobschenie_pokupatelyu")} 
        />
      </div>

      <Button type="submit" className="w-full h-12 rounded-xl text-lg font-semibold" disabled={isLoading}>
        {isLoading && <Loader2 className="w-5 h-5 mr-2 animate-spin" />}
        {t("otpravit_predlozhenie")}</Button>
    </form>
  );
}

"use client"
import { useState } from "react"
import { useForm } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"
import { useRouter } from "next/navigation"
import { RequestFormValues, requestFormSchema } from "../schema"
import { createRequest } from "@/app/actions/requests"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Loader2 } from "lucide-react"
import { CITIES_BY_REGION, guessRegionByCity } from "@/lib/regions"
import { useTranslations } from "next-intl";

export function RequestForm({ categories }: { categories: any[] }) {
    const t = useTranslations();
  const router = useRouter()
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const { register, handleSubmit, setValue, watch, formState: { errors } } = useForm<RequestFormValues>({
    resolver: zodResolver(requestFormSchema),
    defaultValues: {
      title: "",
      categoryId: "",
      description: "",
      condition: "ANY",
      region: "Бишкек",
      city: "Бишкек",
      expiresInDays: 7
    }
  })

  const currentCategory = watch("categoryId")
  const currentCondition = watch("condition")

  const onSubmit = async (data: RequestFormValues) => {
    setIsLoading(true)
    setError(null)

    const formData = new FormData()
    formData.append("title", data.title)
    formData.append("categoryId", data.categoryId)
    formData.append("description", data.description || "")
    if (data.budgetMax) formData.append("budgetMax", data.budgetMax.toString())
    formData.append("condition", data.condition || "ANY")
    formData.append("region", data.region)
    formData.append("city", data.city)
    formData.append("expiresInDays", data.expiresInDays.toString())

    try {
      const result = await createRequest(formData)
      if (result.error) {
        setError(result.error)
        setIsLoading(false)
      } else {
        router.push("/requests")
      }
    } catch (err: any) {
      setError(err.message)
      setIsLoading(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
      {error && (
        <div className="p-4 bg-destructive/10 text-destructive border border-destructive/20 rounded-xl text-sm font-medium">
          {error}
        </div>
      )}

      <div className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="title">{t("chto_vam_nuzhno")}<span className="text-destructive">*</span></Label>
          <Input id="title" {...register("title")} className="h-12 bg-muted/50" placeholder={t("naprimer_iphone_13_128gb_1")} />
          {errors.title && <p className="text-xs text-destructive">{t(errors.title.message as any)}</p>}
        </div>

        <div className="space-y-2">
          <Label>{t("kategoriya")}<span className="text-destructive">*</span></Label>
          <Select 
            value={currentCategory} 
            onValueChange={(val) => setValue("categoryId", val, { shouldValidate: true })}
          >
            <SelectTrigger className="h-12 bg-muted/50">
              <SelectValue placeholder={t("vyberite_samuyu_tochnuyu_kategoriyu")} />
            </SelectTrigger>
            <SelectContent>
              {categories.filter(c => !c.parent_id).map((root) => {
                const children = categories.filter(c => c.parent_id === root.id)
                if (children.length > 0) {
                  return (
                    <div key={root.id}>
                      <div className="px-2 py-1.5 text-sm font-semibold text-muted-foreground">{root.name}</div>
                      {children.map(child => (
                        <SelectItem key={child.id} value={child.id} className="pl-6">{child.name}</SelectItem>
                      ))}
                    </div>
                  )
                }
                return <SelectItem key={root.id} value={root.id}>{root.name}</SelectItem>
              })}
            </SelectContent>
          </Select>
          {errors.categoryId && <p className="text-xs text-destructive">{t(errors.categoryId.message as any)}</p>}
        </div>

        <div className="space-y-2">
          <Label htmlFor="description">{t("opisanie_optsionalno")}</Label>
          <Textarea id="description" {...register("description")} className="bg-muted/50 min-h-[100px]" placeholder={t("utochnite_detali_tsvet_komplekt")} />
          {errors.description && <p className="text-xs text-destructive">{t(errors.description.message as any)}</p>}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="budgetMax">{t("maksimalnaya_tsena_som")}</Label>
            <Input id="budgetMax" type="number" {...register("budgetMax")} className="h-12 bg-muted/50" placeholder={t("naprimer_30000")} />
            {errors.budgetMax && <p className="text-xs text-destructive">{t(errors.budgetMax.message as any)}</p>}
          </div>

          <div className="space-y-2">
            <Label>{t("sostoyanie")}</Label>
            <Select 
              value={currentCondition} 
              onValueChange={(val: any) => setValue("condition", val)}
            >
              <SelectTrigger className="h-12 bg-muted/50">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="ANY">{t("lyuboe")}</SelectItem>
                <SelectItem value="NEW">{t("novoe")}</SelectItem>
                <SelectItem value="USED_LIKE_NEW">{t("kak_novoe")}</SelectItem>
                <SelectItem value="USED_GOOD">{t("horoshee_b_u")}</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
        
        <div className="space-y-2">
          <Label>{t("gorod")}<span className="text-destructive">*</span></Label>
          <Select 
            value={watch("city")} 
            onValueChange={(val) => {
              setValue("city", val, { shouldValidate: true })
              const region = guessRegionByCity(val);
              if (region) {
                setValue("region", region, { shouldValidate: true })
              }
            }}
          >
            <SelectTrigger className="h-12 bg-muted/50">
              <SelectValue placeholder={t("vyberite_gorod")} />
            </SelectTrigger>
            <SelectContent>
              {Object.entries(CITIES_BY_REGION).map(([region, cities]) => (
                <div key={region}>
                  <div className="px-2 py-1.5 text-xs font-semibold text-muted-foreground uppercase tracking-wider bg-muted/30">
                    {region}
                  </div>
                  {cities.map((city: string) => (
                    <SelectItem key={city} value={city} className="pl-6">{city}</SelectItem>
                  ))}
                </div>
              ))}
            </SelectContent>
          </Select>
          {errors.city && <p className="text-xs text-destructive">{t(errors.city.message as any)}</p>}
          {errors.region && <p className="text-xs text-destructive">{t(errors.region.message as any)}</p>}
        </div>

        <div className="space-y-2">
          <Label>{t("srok_aktualnosti")}</Label>
          <Select 
            value={watch("expiresInDays").toString()} 
            onValueChange={(val) => setValue("expiresInDays", parseInt(val))}
          >
            <SelectTrigger className="h-12 bg-muted/50 w-full md:w-1/2">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="3">{t("3_dnya")}</SelectItem>
              <SelectItem value="7">{t("7_dney")}</SelectItem>
              <SelectItem value="14">{t("14_dney")}</SelectItem>
              <SelectItem value="30">{t("30_dney")}</SelectItem>
            </SelectContent>
          </Select>
        </div>

      </div>

      <div className="pt-4 border-t">
        <Button type="submit" className="w-full h-12 rounded-xl text-lg font-semibold" disabled={isLoading}>
          {isLoading && <Loader2 className="w-5 h-5 mr-2 animate-spin" />}
          {t("opublikovat_zapros")}</Button>
      </div>
    </form>
  );
}

"use client"
import { useRouter, useSearchParams, usePathname } from "next/navigation"
import { useTransition, useState, useEffect, useRef } from "react"
import { Button } from "@/components/ui/button"
import { Search, Filter, X } from "lucide-react"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { CategoryPicker } from "@/features/catalog/components/category-picker"

import { AppRouterInstance } from "next/dist/shared/lib/app-router-context.shared-runtime"
import { useTranslations } from "next-intl";

type Category = { id: string, name: string, slug: string, parent_id?: string | null }

function SearchFilter({ searchParams, pathname, router, startTransition }: { searchParams: URLSearchParams, pathname: string, router: AppRouterInstance, startTransition: React.TransitionStartFunction }) {
    const t = useTranslations();
  const [q, setQ] = useState(searchParams.get("q") || "")
  const urlQ = searchParams.get("q") || ""

  useEffect(() => {
    setQ(urlQ)
  }, [urlQ])

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    const current = new URLSearchParams(Array.from(searchParams.entries()))
    if (q) current.set("q", q)
    else current.delete("q")
    
    current.delete("page")
    startTransition(() => {
      router.push(`${pathname}?${current.toString()}`)
    })
  }

  const hasChanges = q !== urlQ

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-2">
      <div className="relative">
